// ===== Geometry (NYS Geometry Regents / NGLS G.*) =====
addUnits("geo",[["gcoord","Coordinate Geometry & Reasoning"],["gline","Lines, Angles & Triangles"],["gcong","Congruence & Transformations"],["gsim","Similarity"],["gtrig","Right-Triangle Trigonometry"],["gcirc","Circles"],["gpoly","Polygons & Quadrilaterals"],["gsolid","Solids, Volume & Modeling"]]);
const gpn=v=>"("+v+")";
const gdeg=n=>n+"°";
// round to d decimals, retrying until the value is not close to a rounding boundary (so calculator noise cannot matter)
const gok=(v,d=1)=>Math.abs((Math.abs(v)*Math.pow(10,d))%1-0.5)>=0.06;
const gsafe=(f,d=1)=>{let v;const m=Math.pow(10,d);do{v=f()}while(Math.abs((Math.abs(v)*m)%1-0.5)<0.06);return v};
// equation a x + b = c x + d with integer solution x (>=2) and positive side values; returns {a,b,c,d,x}
const gEq=()=>{const c=ri(1,5),a=c+ri(1,4),x=ri(2,12),b=ri(1,12),d=(a-c)*x+b;return {a,b,c,d,x}};
const gSvgPar=(hl="")=>`<svg width="190" height="130" viewBox="0 0 190 130" style="display:block;margin:6px 0" aria-label="Two parallel lines cut by a transversal; angles numbered 1 to 8"><line x1="10" y1="35" x2="180" y2="35" stroke="#333" stroke-width="2"/><line x1="10" y1="95" x2="180" y2="95" stroke="#333" stroke-width="2"/><line x1="70" y1="5" x2="125" y2="125" stroke="#3b5bdb" stroke-width="2"/><g font-size="13" font-family="sans-serif" fill="#1c1e21"><text x="68" y="30">1</text><text x="92" y="30">2</text><text x="92" y="52">3</text><text x="68" y="52">4</text><text x="96" y="90">5</text><text x="120" y="90">6</text><text x="120" y="112">7</text><text x="96" y="112">8</text></g><text x="14" y="30" font-size="12" font-family="sans-serif" fill="#555">ℓ</text><text x="14" y="90" font-size="12" font-family="sans-serif" fill="#555">m</text></svg>`;

const GLOG=[{p:"a figure is a square",np:"a figure is not a square",q:"it has four sides",nq:"it does not have four sides"},
 {p:"an angle measures 90°",np:"an angle does not measure 90°",q:"it is a right angle",nq:"it is not a right angle"},
 {p:"two lines are parallel",np:"two lines are not parallel",q:"they never intersect in a plane",nq:"they intersect in a plane"},
 {p:"a triangle is equilateral",np:"a triangle is not equilateral",q:"it is isosceles",nq:"it is not isosceles"},
 {p:"a number is divisible by 6",np:"a number is not divisible by 6",q:"it is divisible by 3",nq:"it is not divisible by 3"},
 {p:"a polygon is a rectangle",np:"a polygon is not a rectangle",q:"it is a parallelogram",nq:"it is not a parallelogram"}];
// ---------------- unit gcoord ----------------
T("dist-mid","gcoord","G.GPE.6","Distance, midpoint & dividing a segment",["pyth","lin-graph"],
 "Coordinate geometry turns geometric facts into arithmetic. The distance formula is the Pythagorean theorem on the coordinate plane; the midpoint averages coordinates.",
 ["Distance: d = √((x₂ − x₁)² + (y₂ − y₁)²).  Midpoint: ((x₁ + x₂)/2, (y₁ + y₂)/2).","To find an endpoint, double the midpoint and subtract the known endpoint (midpoint = average).","A point that is a:b of the way from A to B (a parts to b parts) is A + a/(a+b) · (B − A)."],
 [()=>{let x1,y1,x2,y2;do{x1=ri(-9,9);y1=ri(-9,9);x2=ri(-9,9);y2=ri(-9,9)}while((x1+x2)%2||(y1+y2)%2||(x1===x2&&y1===y2));
   return mk("pair",`Find the midpoint of the segment with endpoints A(${x1}, ${y1}) and B(${x2}, ${y2}).`,`(${(x1+x2)/2}, ${(y1+y2)/2})`,"Average the x-coordinates and average the y-coordinates.",`((${x1} + ${P(x2)})/2, (${y1} + ${P(y2)})/2) = (${(x1+x2)/2}, ${(y1+y2)/2})`,{eqs:[`2*x=(${x1})+(${x2})`,`2*y=(${y1})+(${y2})`]})},
  ()=>{const [a,b,c]=pick(TRI),k=ri(1,2),x1=ri(-8,8),y1=ri(-8,8),sx=pick([-1,1]),sy=pick([-1,1]);const x2=x1+sx*a*k,y2=y1+sy*b*k;
   return mk("num",`Find the distance between (${x1}, ${y1}) and (${x2}, ${y2}).`,c*k,"d = √((x₂ − x₁)² + (y₂ − y₁)²).",`Δx = ${x2-x1}, Δy = ${y2-y1}; √(${(x2-x1)**2} + ${(y2-y1)**2}) = √${(c*k)**2} = ${c*k}`,{js:`Math.hypot((${x2})-(${x1}),(${y2})-(${y1}))`})},
  ()=>{let dx,dy;do{dx=ri(1,9);dy=ri(1,9)}while(SQ(dx*dx+dy*dy)||dx===dy&&false);const x1=ri(-8,8),y1=ri(-8,8),x2=x1+dx*pick([-1,1]),y2=y1+dy*pick([-1,1]);
   return mk("expr",`Find the distance between (${x1}, ${y1}) and (${x2}, ${y2}). Leave it as a simplified radical.`,radStr(dx*dx+dy*dy),"Use the distance formula, then simplify the radical.",`√(${dx}² + ${dy}²) = √${dx*dx+dy*dy} = ${radStr(dx*dx+dy*dy).replace(/sqrt\((\d+)\)/,"√$1")}`,{form:"rad",pe:`Math.hypot((${x2})-(${x1}),(${y2})-(${y1}))`})},
  ()=>{const ax=ri(-9,9),ay=ri(-9,9),mx=ri(-8,8),my=ri(-8,8);
   return mk("pair",`The midpoint of AB is M(${mx}, ${my}) and A is (${ax}, ${ay}). Find the coordinates of B.`,`(${2*mx-ax}, ${2*my-ay})`,"Midpoint = average, so B = 2M − A.",`(2·${P(mx)} − ${P(ax)}, 2·${P(my)} − ${P(ay)}) = (${2*mx-ax}, ${2*my-ay})`,{eqs:[`(${ax})+x=2*(${mx})`,`(${ay})+y=2*(${my})`]})},
  ()=>{const a=ri(1,3),b=ri(1,3),t=a+b,x1=ri(-6,6),y1=ri(-6,6),dx=t*ri(-3,3),dy=t*ri(-3,3);const x2=x1+dx,y2=y1+dy;
   return mk("pair",`Point P lies on segment AB with A(${x1}, ${y1}) and B(${x2}, ${y2}) so that AP : PB = ${a} : ${b}. Find P.`,`(${x1+a*dx/t}, ${y1+a*dy/t})`,"P is a/(a+b) of the way from A to B.",`Move ${a}/${t} of the way: (${x1} + ${a}/${t}·${P(dx)}, ${y1} + ${a}/${t}·${P(dy)}) = (${x1+a*dx/t}, ${y1+a*dy/t})`,{eqs:[`${t}*x=${b}*(${x1})+${a}*(${x2})`,`${t}*y=${b}*(${y1})+${a}*(${y2})`]})}]);
T("seg-add","gcoord","G.CO.1","Segments, angles & the addition postulates",["twostep-eq","angle-rel"],
 "Basic geometry facts become equations. If B is between A and C then AB + BC = AC. A midpoint splits a segment into two equal parts; an angle bisector splits an angle into two equal angles.",
 ["Segment addition: AB + BC = AC when B lies between A and C.  Angle addition: m∠AOB + m∠BOC = m∠AOC.","Midpoint M: AM = MB.  Angle bisector: the two smaller angles are equal.","Complementary angles sum to 90°, supplementary angles sum to 180°. Write the relationship as an equation, solve, then substitute back."],
 [()=>{const a=ri(1,5),c=ri(1,5),x=ri(2,10),b=ri(1,9),d=ri(1,9),e=(a+c)*x+b+d;
   return mk("num",`Point B is between A and C. AB = ${lin(a,b)}, BC = ${lin(c,d)} and AC = ${e}. Find x.`,x,"Segment addition: AB + BC = AC.",`${lin(a,b)} + ${lin(c,d)} = ${e} → ${a+c}x + ${b+d} = ${e} → x = ${x}`,{js:`${x}`,eqs:[`(${a})*x+${b}+(${c})*x+${d}=${e}`]})},
  ()=>{const {a,b,c,d,x}=gEq();return mk("num",`M is the midpoint of AB. AM = ${lin(a,b)} and MB = ${lin(c,d)}. Find the length of AB.`,2*(a*x+b),"A midpoint makes the two parts equal: set AM = MB, solve for x, then AB = 2·AM.",`${lin(a,b)} = ${lin(c,d)} → ${a-c}x = ${d-b} → x = ${x}; AM = ${a*x+b}, so AB = ${2*(a*x+b)}`,{js:`2*(${a}*${x}+${b})`,eqs:[`(${a})*(${x})+${b}=(${c})*(${x})+${d}`]})},
  ()=>{const {a,b,c,d,x}=gEq();return mk("num",`Ray BD bisects ∠ABC. m∠ABD = (${lin(a,b)})° and m∠DBC = (${lin(c,d)})°. Find m∠ABC.`,2*(a*x+b),"A bisector makes two equal angles: set them equal, solve, and double.",`${lin(a,b)} = ${lin(c,d)} → x = ${x}; each half is ${a*x+b}°, so m∠ABC = ${2*(a*x+b)}°`,{js:`2*(${a}*${x}+${b})`,eqs:[`(${a})*(${x})+${b}=(${c})*(${x})+${d}`]})},
  ()=>{let a,c,b,d,x;do{a=ri(1,5);c=ri(1,5);x=ri(2,12);b=ri(1,20);d=180-(a+c)*x-b}while(d<1||a*x+b>=179);
   return mk("num",`Two angles are supplementary. Their measures are (${lin(a,b)})° and (${lin(c,d)})°. Find the measure of the first angle.`,a*x+b,"Supplementary angles sum to 180°.",`${lin(a,b)} + ${lin(c,d)} = 180 → ${a+c}x = ${180-b-d} → x = ${x}; first angle = ${a*x+b}°`,{js:`${a}*${x}+${b}`,eqs:[`(${a})*(${x})+${b}+(${c})*(${x})+${d}=180`]})},
  ()=>{const a=ri(1,4),c=ri(1,4),x=ri(3,12),b=ri(1,9),d=ri(1,9),e=(a+c)*x+b+d;
   return mk("num",`Point B lies inside ∠AOC. m∠AOB = (${lin(a,b)})°, m∠BOC = (${lin(c,d)})° and m∠AOC = ${e}°. Find x.`,x,"Angle addition: m∠AOB + m∠BOC = m∠AOC.",`${a+c}x + ${b+d} = ${e} → x = ${x}`,{js:`${x}`,eqs:[`(${a})*x+${b}+(${c})*x+${d}=${e}`]})}]);
T("conditional","gcoord","G.CO.9","Conditional statements & logic",["seg-add"],
 "Geometry is built on logical statements. A conditional 'If p, then q' has three relatives: converse, inverse and contrapositive. Only the contrapositive is always equivalent to the original.",
 ["Conditional: p → q.  Converse: q → p.  Inverse: not p → not q.  Contrapositive: not q → not p.","A conditional and its contrapositive always have the same truth value; the converse and inverse are equivalent to each other.","A conditional is false only when p is true and q is false; one counterexample disproves a conditional."],
 [()=>{const S=pick(GLOG);const kind=pick(["converse","inverse","contrapositive"]);
   const ans={converse:`If ${S.q}, then ${S.p}.`,inverse:`If ${S.np}, then ${S.nq}.`,contrapositive:`If ${S.nq}, then ${S.np}.`};
   return mcq(`Statement: “If ${S.p}, then ${S.q}.” Which statement is its <b>${kind}</b>?`,ans[kind],[`If ${S.p}, then ${S.q}.`,...["converse","inverse","contrapositive"].filter(k=>k!==kind).map(k=>ans[k])],`Converse swaps p and q; inverse negates both; contrapositive swaps and negates.`,`The ${kind} is: ${ans[kind]}`)},
  ()=>{const S=pick(GLOG);const ans=`If ${S.nq}, then ${S.np}.`;
   return mcq(`Which statement is logically equivalent to “If ${S.p}, then ${S.q}”?`,ans,[`If ${S.q}, then ${S.p}.`,`If ${S.np}, then ${S.nq}.`,`${S.p[0].toUpperCase()+S.p.slice(1)} and ${S.nq}.`],"Only the contrapositive is always equivalent to the conditional.",`Contrapositive: ${ans}`)},
  ()=>{const k=pick([3,5,7,9]),good=k*pick([1,3,5]);const wr=[2*k,4*k,6*k];
   return mcq(`Which number is a counterexample to the statement “If a number is a multiple of ${k}, then it is a multiple of ${2*k}”?`,String(good),wr.map(String),"A counterexample satisfies the 'if' part but not the 'then' part.",`${good} is a multiple of ${k} but is odd, so it is not a multiple of ${2*k}. (${wr.join(", ")} are multiples of ${2*k}.)`)},
  ()=>{const p=Math.random()<0.5,q=Math.random()<0.5,which=pick(["conditional","converse","contrapositive","inverse"]);
   const val={conditional:!p||q,converse:!q||p,contrapositive:q||!p,inverse:p||!q};
   return mcq(`Suppose p is ${p?"true":"false"} and q is ${q?"true":"false"}. What is the truth value of the ${which} of “If p, then q”?`,val[which]?"True":"False",[val[which]?"False":"True"],"A conditional 'If A, then B' is false only when A is true and B is false.",`${which==="conditional"?"p → q":which==="converse"?"q → p":which==="inverse"?"not p → not q":"not q → not p"}: antecedent ${which==="conditional"?p:which==="converse"?q:which==="inverse"?!p:!q}, consequent ${which==="conditional"?q:which==="converse"?p:which==="inverse"?!q:!p} → ${val[which]?"True":"False"}`)}]);

// ---------------- unit gline ----------------
const GREL={1:{3:"vertical angles",5:"corresponding angles",7:"alternate exterior angles",2:"a linear pair",4:"a linear pair",6:"same-side exterior angles",8:"same-side exterior angles"}};
const GPAIRS=[[1,5,"corresponding angles"],[2,6,"corresponding angles"],[3,7,"corresponding angles"],[4,8,"corresponding angles"],[3,5,"alternate interior angles"],[4,6,"alternate interior angles"],[3,6,"same-side interior angles"],[4,5,"same-side interior angles"],[1,7,"alternate exterior angles"],[2,8,"alternate exterior angles"],[1,3,"vertical angles"],[2,4,"vertical angles"],[5,7,"vertical angles"],[6,8,"vertical angles"],[1,2,"a linear pair"],[2,3,"a linear pair"],[3,4,"a linear pair"],[1,4,"a linear pair"],[5,6,"a linear pair"],[6,7,"a linear pair"],[7,8,"a linear pair"],[5,8,"a linear pair"]];
const GRELS=["corresponding angles","alternate interior angles","same-side interior angles","alternate exterior angles","vertical angles","a linear pair"];
T("par-lines","gline","G.CO.9","Parallel lines & transversals",["seg-add","angles-parallel"],
 "When a transversal crosses two parallel lines it creates eight angles that are either equal or supplementary. Naming the relationship tells you which.",
 ["Equal (congruent): corresponding, alternate interior, alternate exterior and vertical angles.","Supplementary (sum 180°): same-side interior angles and linear pairs.","Set up an equation from the relationship, solve for x, then substitute to get the angle measures."],
 [()=>{const rel=pick(["corresponding angles","alternate interior angles","alternate exterior angles","vertical angles"]);const {a,b,c,d,x}=gEq();
   return mk("num",`Two parallel lines are cut by a transversal. Two ${rel} measure (${lin(a,b)})° and (${lin(c,d)})°. Find x.`,x,`${rel[0].toUpperCase()+rel.slice(1)} are equal here, so set the expressions equal.`,`${lin(a,b)} = ${lin(c,d)} → ${a-c}x = ${d-b} → x = ${x}`,{js:`${x}`,eqs:[`(${a})*x+${b}=(${c})*x+${d}`]})},
  ()=>{let a,c,b,d,x;do{a=ri(1,5);c=ri(1,5);x=ri(3,14);b=ri(1,20);d=180-(a+c)*x-b}while(d<1);const rel=pick(["same-side interior angles","a linear pair"]);
   return mk("num",`Two parallel lines are cut by a transversal. ${rel==="a linear pair"?"Two angles forming a linear pair":"Two same-side interior angles"} measure (${lin(a,b)})° and (${lin(c,d)})°. Find the measure of the larger of the two angles.`,Math.max(a*x+b,c*x+d),"These angles are supplementary: their measures add to 180°.",`${lin(a,b)} + ${lin(c,d)} = 180 → x = ${x}; angles are ${a*x+b}° and ${c*x+d}°`,{js:`Math.max(${a}*${x}+${b},${c}*${x}+${d})`,eqs:[`(${a})*(${x})+${b}+(${c})*(${x})+${d}=180`]})},
  ()=>{const [i,j,rel]=pick(GPAIRS);const f=Math.random()<0.5;return mcq(`In the figure, ℓ ∥ m and the blue line is a transversal.${gSvgPar()} What is the relationship between ∠${f?i:j} and ∠${f?j:i}?`,rel,GRELS.filter(r=>r!==rel).slice(0,3),"Locate the two angles: are they between the parallel lines (interior) or outside (exterior); on the same or opposite sides of the transversal?",`∠${i} and ∠${j} are ${rel}.`)},
  ()=>{const th=ri(2,17)*10+5,k=ri(2,8);const eqv=k%2===1,ans=eqv?th:180-th;if(k===1)return null;
   return mk("num",`In the figure, ℓ ∥ m. If m∠1 = ${th}°, find m∠${k}.${gSvgPar()}`,ans,"Angles 1, 3, 5, 7 are all equal; angles 2, 4, 6, 8 are all equal; each odd/even pair is supplementary.",`∠${k} is ${eqv?"equal to ∠1 (corresponding/vertical/alternate)":"supplementary to ∠1"}: ${eqv?th:`180 − ${th} = ${180-th}`}°`,{js:`${eqv?th:180-th}`})}].map(g=>()=>{let q;do{q=g()}while(!q);return q}));
const gRetry=g=>()=>{let q;do{q=g()}while(!q);return q};
T("tri-ang-sum","gline","G.CO.10","Triangle angle relationships with algebra",["par-lines","tri-angles"],
 "The three interior angles of a triangle add to 180°. An exterior angle equals the sum of the two remote interior angles.",
 ["Interior angles: sum = 180°.","Exterior angle = sum of the two remote (non-adjacent) interior angles; it also equals 180° minus the adjacent interior angle.","Write an equation, solve for x, then substitute back to find requested angles."],
 [()=>{let a,c,e,b,d,f,x;do{a=ri(1,4);c=ri(1,4);e=ri(1,4);x=ri(4,14);b=ri(1,20);d=ri(1,20);f=180-(a+c+e)*x-b-d}while(f<1);
   return mk("num",`The angles of a triangle measure (${lin(a,b)})°, (${lin(c,d)})° and (${lin(e,f)})°. Find x.`,x,"Interior angles add to 180°.",`${a+c+e}x + ${b+d+f} = 180 → x = ${x}`,{js:`${x}`,eqs:[`(${a})*x+${b}+(${c})*x+${d}+(${e})*x+${f}=180`]})},
  ()=>{let a,c,e,b,d,f,x;do{a=ri(1,4);c=ri(1,4);e=ri(1,4);x=ri(4,14);b=ri(1,20);d=ri(1,20);f=180-(a+c+e)*x-b-d}while(f<1);
   const ang=[a*x+b,c*x+d,e*x+f];return mk("num",`The angles of a triangle measure (${lin(a,b)})°, (${lin(c,d)})° and (${lin(e,f)})°. Find the measure of the largest angle.`,Math.max(...ang),"Solve the angle sum = 180° for x, then evaluate each angle.",`${a+c+e}x + ${b+d+f} = 180 → x = ${x}; angles ${ang.join("°, ")}°`,{js:`Math.max(${a}*${x}+${b},${c}*${x}+${d},${e}*${x}+${f})`,eqs:[`(${a})*(${x})+${b}+(${c})*(${x})+${d}+(${e})*(${x})+${f}=180`]})},
  ()=>{const r1=ri(20,80),r2=ri(20,80),ex=r1+r2;
   return mk("num",`An exterior angle of a triangle measures ${ex}°. One remote interior angle measures ${r1}°. Find the other remote interior angle.`,r2,"Exterior angle = sum of the two remote interior angles.",`${ex} − ${r1} = ${r2}`,{js:`${ex}-${r1}`})},
  ()=>{const c=ri(1,4),a=c+ri(1,4),x=ri(2,12),b=ri(1,12),d=ri(1,12),ext=a*x+b,rem1=c*x+d,rem2=ext-rem1;if(rem2<1)return null;
   return mk("num",`An exterior angle of a triangle measures (${lin(a,b)})°. The remote interior angles measure (${lin(c,d)})° and ${rem2}°. Find x.`,x,"Exterior angle = sum of the remote interior angles.",`${lin(a,b)} = ${lin(c,d)} + ${rem2} → ${a-c}x = ${d+rem2-b} → x = ${x}`,{js:`${x}`,eqs:[`(${a})*x+${b}=(${c})*x+${d}+${rem2}`]})},
  ()=>{const A=ri(30,100),B=ri(30,100);if(A+B>165)return null;return mk("num",`In △ABC, m∠A = ${A}° and m∠B = ${B}°. Find the exterior angle at C.`,A+B,"The exterior angle at C equals the sum of the remote interior angles A and B (or 180° − m∠C).",`${A} + ${B} = ${A+B}°; check: 180 − (180 − ${A} − ${B}) = ${A+B}`,{js:`180-(180-${A}-${B})`})}].map(gRetry));
T("tri-ineq","gline","G.CO.10","Triangle inequalities",["tri-ang-sum"],
 "Not every set of three lengths makes a triangle, and sides and angles are linked in size: the longest side is opposite the largest angle.",
 ["Triangle inequality: the sum of any two sides must be greater than the third side.","If two sides are a and b, the third side c satisfies |a − b| < c < a + b.","The largest angle is opposite the longest side; the smallest angle is opposite the shortest side."],
 [()=>{const ok=()=>{const a=ri(2,15),b=ri(2,15),c=ri(2,30);return [a,b,c]};const valid=t=>{const [a,b,c]=t;return a+b>c&&a+c>b&&b+c>a};
   let good,bads=new Set();do{good=ok()}while(!valid(good));while(bads.size<3){const t=ok();if(!valid(t))bads.add(t.join(", "))}
   return mcq(`Which set of side lengths can form a triangle?`,good.join(", "),[...bads],"The two shorter sides must add to more than the longest side.",`${good.join(", ")}: the two smaller sides sum to ${good.slice().sort((x,y)=>x-y).slice(0,2).reduce((p,q)=>p+q)}, which is more than ${Math.max(...good)}. In each other set, the two smaller sides do not exceed the largest.`)},
  ()=>{let a,b;do{a=ri(3,20);b=ri(3,20)}while(a===b);return mk("num",`Two sides of a triangle measure ${a} and ${b}. What is the smallest whole-number length the third side can have?`,Math.abs(a-b)+1,"Third side > |a − b| and < a + b.",`The third side must be greater than ${Math.abs(a-b)}, so the smallest whole number is ${Math.abs(a-b)+1}`,{js:`Math.abs(${a}-${b})+1`})},
  ()=>{let a,b;do{a=ri(3,20);b=ri(3,20)}while(a===b);return mk("num",`Two sides of a triangle measure ${a} and ${b}. What is the largest whole-number length the third side can have?`,a+b-1,"Third side < a + b.",`The third side must be less than ${a+b}, so the largest whole number is ${a+b-1}`,{js:`${a}+${b}-1`})},
  ()=>{let a,b;do{a=ri(3,20);b=ri(3,20)}while(a===b);return mk("num",`Two sides of a triangle measure ${a} and ${b}. How many whole-number lengths are possible for the third side?`,2*Math.min(a,b)-1,"Count the whole numbers strictly between |a − b| and a + b.",`From ${Math.abs(a-b)+1} to ${a+b-1}: ${a+b-1} − ${Math.abs(a-b)+1} + 1 = ${2*Math.min(a,b)-1}`,{js:`(${a}+${b}-1)-(Math.abs(${a}-${b})+1)+1`})},
  ()=>{let A,B,C;do{A=ri(25,100);B=ri(25,100);C=180-A-B}while(C<20||A===B||B===C||A===C);const nm=["A","B","C"],ang=[A,B,C],opp=["BC","AC","AB"];const big=ang.indexOf(Math.max(...ang));
   return mcq(`In △ABC, m∠A = ${A}°, m∠B = ${B}° and m∠C = ${C}°. Which side is the longest?`,opp[big],opp.filter((_,i)=>i!==big),"The longest side is opposite the largest angle.",`The largest angle is ∠${nm[big]} = ${ang[big]}°, so the longest side is the one opposite it: ${opp[big]}.`)}]);
T("isos-tri","gline","G.CO.10","Isosceles & equilateral triangles",["tri-ang-sum"],
 "In an isosceles triangle the angles opposite the equal sides (base angles) are equal. An equilateral triangle has three equal sides and three 60° angles.",
 ["Base angles of an isosceles triangle are equal: base angle = (180° − vertex angle) ÷ 2.","Equal sides ↔ equal opposite angles, in both directions.","Equilateral: all sides equal, all angles 60°."],
 [()=>{const v=2*ri(10,80);return mk("num",`The vertex angle of an isosceles triangle measures ${v}°. Find the measure of one base angle.`,(180-v)/2,"Base angles are equal and the three angles add to 180°.",`(180 − ${v}) ÷ 2 = ${(180-v)/2}°`,{js:`(180-${v})/2`})},
  ()=>{const b=ri(20,80);return mk("num",`A base angle of an isosceles triangle measures ${b}°. Find the vertex angle.`,180-2*b,"Vertex = 180° − 2 × base angle.",`180 − 2(${b}) = ${180-2*b}°`,{js:`180-2*${b}`})},
  ()=>{const {a,b,c,d,x}=gEq();return mk("num",`In isosceles △ABC with AB = AC, AB = ${lin(a,b)} and AC = ${lin(c,d)}. Find the length of AB.`,a*x+b,"Equal sides: set the expressions equal, solve for x, then substitute.",`${lin(a,b)} = ${lin(c,d)} → x = ${x}; AB = ${a*x+b}`,{js:`${a}*${x}+${b}`,eqs:[`(${a})*(${x})+${b}=(${c})*(${x})+${d}`]})},
  ()=>{const a=ri(1,5),x=ri(2,12),b=60-a*x;if(b===0)return null;return mk("num",`Each angle of an equilateral triangle measures (${lin(a,b)})°. Find x.`,x,"Every angle of an equilateral triangle is 60°.",`${lin(a,b)} = 60 → ${a}x = ${60-b} → x = ${x}`,{js:`${x}`,eqs:[`(${a})*x+(${b})=60`]})},
  ()=>{const {a,b,c,d,x}=gEq();return mk("num",`In △ABC, m∠B = (${lin(a,b)})° and m∠C = (${lin(c,d)})° and AB = AC. Find m∠B.`,a*x+b,"AB = AC means the angles opposite them (∠C and ∠B) are equal.",`${lin(a,b)} = ${lin(c,d)} → x = ${x}; m∠B = ${a*x+b}°`,{js:`${a}*${x}+${b}`,eqs:[`(${a})*(${x})+${b}=(${c})*(${x})+${d}`]})}].map(gRetry));
T("tri-cent","gline","G.CO.10","Midsegments, medians & centers of a triangle",["dist-mid","tri-ang-sum"],
 "Special segments in a triangle have special properties. A midsegment joins two midpoints and is parallel to, and half as long as, the third side. The medians meet at the centroid, which splits each median 2 : 1.",
 ["Midsegment = ½ × the third side.","Centroid (medians): average of the vertex coordinates; it is 2/3 of the way along each median from the vertex.","Perpendicular bisectors → circumcenter; angle bisectors → incenter; altitudes → orthocenter."],
 [()=>{const L=2*ri(3,25);return mk("num",`DE is a midsegment of △ABC (D and E are midpoints of AB and AC). If BC = ${L}, find DE.`,L/2,"A midsegment is half the length of the side it is parallel to.",`${L} ÷ 2 = ${L/2}`,{js:`${L}/2`})},
  ()=>{const a=ri(2,6),x=ri(2,12),b=ri(1,9),c=ri(1,3),d=ri(-5,6);const BC=a*x+b;if(BC%2)return null;const DE=BC/2;const c1=DE-0;
   const k=ri(1,4),e=DE-k*x;return mk("num",`DE is a midsegment parallel to BC. DE = ${lin(k,e)} and BC = ${lin(a,b)}. Find x.`,x,"DE = ½·BC, so 2·DE = BC.",`2(${lin(k,e)}) = ${lin(a,b)} → ${2*k}x + ${2*e} = ${a}x + ${b} → x = ${x}`,{js:`${x}`,eqs:[`2*((${k})*x+(${e}))=(${a})*x+${b}`]})},
  ()=>{let x1,y1,x2,y2,x3,y3;do{x1=ri(-9,9);y1=ri(-9,9);x2=ri(-9,9);y2=ri(-9,9);x3=ri(-9,9);y3=ri(-9,9)}while((x1+x2+x3)%3||(y1+y2+y3)%3||(x2-x1)*(y3-y1)-(x3-x1)*(y2-y1)===0);
   return mk("pair",`Find the centroid of the triangle with vertices (${x1}, ${y1}), (${x2}, ${y2}) and (${x3}, ${y3}).`,`(${(x1+x2+x3)/3}, ${(y1+y2+y3)/3})`,"The centroid is the average of the three vertices.",`((${x1} + ${P(x2)} + ${P(x3)})/3, (${y1} + ${P(y2)} + ${P(y3)})/3) = (${(x1+x2+x3)/3}, ${(y1+y2+y3)/3})`,{eqs:[`3*x=(${x1})+(${x2})+(${x3})`,`3*y=(${y1})+(${y2})+(${y3})`]})},
  ()=>{const m=3*ri(2,12);return mk("num",`The median from vertex A of △ABC has length ${m}. How far is the centroid from vertex A?`,2*m/3,"The centroid is 2/3 of the way from the vertex along the median.",`(2/3)(${m}) = ${2*m/3}`,{js:`2*${m}/3`})},
  ()=>{const items=[["perpendicular bisectors of the sides","circumcenter"],["angle bisectors","incenter"],["altitudes","orthocenter"],["medians","centroid"]];const [d,n]=pick(items);
   return mcq(`The point where the ${d} of a triangle meet is called the…`,n,["circumcenter","incenter","orthocenter","centroid"].filter(x=>x!==n),"Match each set of segments to its center.",`${d[0].toUpperCase()+d.slice(1)} → ${n}. (circumcenter: perpendicular bisectors; incenter: angle bisectors; orthocenter: altitudes; centroid: medians)`)}].map(gRetry));

// ---------------- unit gcong ----------------
T("refl-rot","gcong","G.CO.5","Reflections & rotations in the coordinate plane",["reflect","rotate"],
 "Rigid motions can use any line or point, not just the axes and origin. A reflection over a line sends each point to the mirror point on the other side; a rotation turns the plane about a center.",
 ["Reflect over x = k: (a, b) → (2k − a, b).  Over y = k: (a, b) → (a, 2k − b).  Over y = x: (a, b) → (b, a).  Over y = −x: (a, b) → (−b, −a).","Rotate 180° about (h, k): (a, b) → (2h − a, 2k − b).","Rotate about (h, k): shift so the center is the origin, rotate, then shift back. 90° counterclockwise: (u, v) → (−v, u)."],
 [()=>{const a=ri(-9,9),b=ri(-9,9),k=ri(-6,6);return mk("pair",`Reflect the point (${a}, ${b}) over the line x = ${k}.`,`(${2*k-a}, ${b})`,"The x-coordinate moves to the mirror position: new x = 2k − x.",`2(${k}) − ${P(a)} = ${2*k-a}; y stays ${b}`,{eqs:[`x+(${a})=2*(${k})`,`y=(${b})`]})},
  ()=>{const a=ri(-9,9),b=ri(-9,9),k=ri(-6,6);return mk("pair",`Reflect the point (${a}, ${b}) over the line y = ${k}.`,`(${a}, ${2*k-b})`,"The y-coordinate moves to the mirror position: new y = 2k − y.",`x stays ${a}; 2(${k}) − ${P(b)} = ${2*k-b}`,{eqs:[`x=(${a})`,`y+(${b})=2*(${k})`]})},
  ()=>{const a=ri(-9,9),b=ri(-9,9),neg=Math.random()<0.5;return mk("pair",`Reflect the point (${a}, ${b}) over the line y = ${neg?"-x":"x"}.`,neg?`(${-b}, ${-a})`:`(${b}, ${a})`,neg?"Over y = −x: (a, b) → (−b, −a).":"Over y = x: swap the coordinates.",neg?`(−${P(b)}, −${P(a)}) = (${-b}, ${-a})`:`(${b}, ${a})`,{eqs:neg?[`x+(${b})=0`,`y+(${a})=0`]:[`x=(${b})`,`y=(${a})`]})},
  ()=>{const h=ri(-5,5),k=ri(-5,5),a=ri(-8,8),b=ri(-8,8);return mk("pair",`Rotate the point (${a}, ${b}) 180° about the point (${h}, ${k}).`,`(${2*h-a}, ${2*k-b})`,"A 180° rotation about C sends P to the point on the opposite side of C: P' = 2C − P.",`(2(${h}) − ${P(a)}, 2(${k}) − ${P(b)}) = (${2*h-a}, ${2*k-b})`,{eqs:[`x+(${a})=2*(${h})`,`y+(${b})=2*(${k})`]})},
  ()=>{const h=ri(-5,5),k=ri(-5,5);let a,b;do{a=ri(-8,8);b=ri(-8,8)}while(a===h&&b===k);const ccw=Math.random()<0.5,u=a-h,v=b-k;const nu=ccw?-v:v,nv=ccw?u:-u;const d2=u*u+v*v;
   return mk("pair",`Rotate the point (${a}, ${b}) 90° ${ccw?"counterclockwise":"clockwise"} about the point (${h}, ${k}).`,`(${h+nu}, ${k+nv})`,"Shift so the center is the origin, rotate, then shift back.",`Relative position (${u}, ${v}) → (${nu}, ${nv}); add the center: (${h+nu}, ${k+nv})`,{eqs:[`(x-(${h}))**2+(y-(${k}))**2=${d2}`,`(${u})*(x-(${h}))+(${v})*(y-(${k}))=0`,`(${u})*(y-(${k}))-(${v})*(x-(${h}))=${ccw?d2:-d2}`]})}]);
const GTRI=[["A","B","C","D","E","F"],["P","Q","R","X","Y","Z"],["J","K","L","M","N","O"],["G","H","I","S","T","U"]];
T("cong-tri","gcong","G.SRT.5","Triangle congruence criteria",["transform-seq","tri-ang-sum"],
 "Two triangles are congruent when a rigid motion maps one onto the other. You do not need all six matching parts: certain minimal sets of three guarantee congruence.",
 ["Valid criteria: SSS, SAS (angle between the two sides), ASA (side between the two angles), AAS, and HL (right triangles only).","SSA (the angle is not between the sides) and AAA do NOT guarantee congruence.","Always check where the angle sits relative to the sides: 'included' means between them."],
 [()=>{const [A,B,C,D,E,F]=pick(GTRI);const sd=(x,y,X,Y)=>`${x}${y} ≅ ${X}${Y}`,an=(x,X)=>`∠${x} ≅ ∠${X}`;
   const cfgs=[["SSS",[sd(A,B,D,E),sd(B,C,E,F),sd(A,C,D,F)]],["SAS",[sd(A,B,D,E),an(B,E),sd(B,C,E,F)]],["ASA",[an(A,D),sd(A,B,D,E),an(B,E)]],["AAS",[an(A,D),an(B,E),sd(B,C,E,F)]],["HL",[`∠B and ∠E are right angles`,sd(A,C,D,F),sd(A,B,D,E)]]];
   const [name,parts]=pick(cfgs);return mcq(`In △${A}${B}${C} and △${D}${E}${F}: ${parts.join("; ")}. Which criterion proves the triangles congruent?`,name,["SSS","SAS","ASA","AAS","HL"].filter(x=>x!==name).slice(0,3).concat([]),"Compare the given parts to the valid criteria, checking which parts are included.",`The given parts form ${name}.`)},
  ()=>{const [A,B,C,D,E,F]=pick(GTRI);const sd=(x,y,X,Y)=>`${x}${y} ≅ ${X}${Y}`,an=(x,X)=>`∠${x} ≅ ∠${X}`;
   const cfgs=[["SSA",[sd(A,B,D,E),sd(B,C,E,F),an(A,D)]],["AAA",[an(A,D),an(B,E),an(C,F)]]];const [nm,parts]=pick(cfgs);
   return mcq(`In △${A}${B}${C} and △${D}${E}${F}: ${parts.join("; ")}. What can you conclude?`,"The triangles are not necessarily congruent",["The triangles are congruent by SAS","The triangles are congruent by ASA","The triangles are congruent by SSS"],"Check the given parts against the valid criteria.",nm==="SSA"?"The angle is not between the two sides (SSA), which is not a valid criterion.":"Three equal angles (AAA) only guarantee similarity, not congruence.")},
  ()=>{const [A,B,C,D,E,F]=pick(GTRI);const crit=pick(["SAS","ASA","AAS"]);const ans={SAS:`${A}${C} ≅ ${D}${F}`,ASA:`∠${B} ≅ ∠${E}`,AAS:`∠${C} ≅ ∠${F}`}[crit];
   return mcq(`In △${A}${B}${C} and △${D}${E}${F}, ${A}${B} ≅ ${D}${E} and ∠${A} ≅ ∠${D}. Which additional statement would prove the triangles congruent by ${crit}?`,ans,[`${A}${C} ≅ ${D}${F}`,`∠${B} ≅ ∠${E}`,`∠${C} ≅ ∠${F}`,`${B}${C} ≅ ${E}${F}`].filter(x=>x!==ans).slice(0,3).map((x,i,ar)=>x).concat([]).slice(0,3),"Place the given parts in the pattern of the criterion and see which part is missing.",`${crit}: ${crit==="SAS"?"the angle must be between the two sides, so add the other side at "+A:crit==="ASA"?"the side AB must be between two angles, so add the angle at "+B:"two angles and a side that is not between them: add the angle at "+C}.`)},
  ()=>{const valid=pick(["SSS","SAS","ASA","AAS","HL"]);const bad=pick(["SSA","AAA"]);return mcq("Which of the following is NOT a valid way to prove two triangles congruent?",bad,["SSS","SAS","ASA","AAS","HL"].filter(x=>x!==valid).slice(0,2).concat([valid]),"SSA and AAA do not determine a unique triangle.",bad==="SSA"?"With SSA, two different triangles can fit the same data (the ambiguous case).":"AAA fixes the shape but not the size, so the triangles may be similar but not congruent.")}]);
T("cpctc","gcong","G.SRT.5","Corresponding parts of congruent triangles",["cong-tri"],
 "Once triangles are congruent, all their corresponding parts are congruent (CPCTC). The order of the letters in a congruence statement tells you which parts match.",
 ["In △ABC ≅ △DEF, A↔D, B↔E, C↔F: side AB ↔ DE, angle B ↔ angle E, and so on.","Corresponding sides and angles have equal measures: set the expressions equal and solve.","Perimeters of congruent triangles are equal."],
 [()=>{const {a,b,c,d,x}=gEq();return mk("num",`△ABC ≅ △DEF. AB = ${lin(a,b)} and DE = ${lin(c,d)}. Find x.`,x,"Corresponding sides are equal.",`${lin(a,b)} = ${lin(c,d)} → ${a-c}x = ${d-b} → x = ${x}`,{js:`${x}`,eqs:[`(${a})*x+${b}=(${c})*x+${d}`]})},
  ()=>{const {a,b,c,d,x}=gEq();return mk("num",`△ABC ≅ △DEF with m∠A = (${lin(a,b)})° and m∠D = (${lin(c,d)})°. Find m∠A.`,a*x+b,"Corresponding angles are equal: solve for x, then substitute.",`${lin(a,b)} = ${lin(c,d)} → x = ${x}; m∠A = ${a*x+b}°`,{js:`${a}*${x}+${b}`,eqs:[`(${a})*(${x})+${b}=(${c})*(${x})+${d}`]})},
  ()=>{const T1=pick(GTRI),idx=pick([[0,1],[1,2],[0,2]]);const perm=shuffle([0,1,2]);const t1=perm.map(i=>T1[i]),t2=perm.map(i=>T1[i+3]);
   const [i,j]=idx;const ans=t2[i]+t2[j],other=[[0,1],[1,2],[0,2]].map(([p,q])=>t2[p]+t2[q]).filter(x=>x!==ans);
   return mcq(`△${t1.join("")} ≅ △${t2.join("")}. Which side of △${t2.join("")} corresponds to ${t1[i]}${t1[j]}?`,ans,other,"Match letters by position in the congruence statement.",`${t1[i]} is in position ${i+1} and ${t1[j]} is in position ${j+1}; the same positions in the second triangle give ${ans}.`)},
  ()=>{const T1=pick(GTRI),k=pick([0,1,2]);const perm=shuffle([0,1,2]);const t1=perm.map(i=>T1[i]),t2=perm.map(i=>T1[i+3]);
   return mcq(`△${t1.join("")} ≅ △${t2.join("")}. Which angle of △${t2.join("")} is congruent to ∠${t1[k]}?`,`∠${t2[k]}`,[0,1,2].filter(i=>i!==k).map(i=>`∠${t2[i]}`),"Corresponding vertices are in the same position in the congruence statement.",`${t1[k]} is in position ${k+1}, matching ${t2[k]}.`)},
  ()=>{const a=ri(3,15),b=ri(3,15),c=ri(3,15);return mk("num",`△ABC ≅ △XYZ with AB = ${a}, BC = ${b} and XZ = ${c}. Find the perimeter of △XYZ.`,a+b+c,"Congruent triangles have equal sides: XY = AB, YZ = BC, and XZ = AC.",`AC = XZ = ${c}, so the perimeter is ${a} + ${b} + ${c} = ${a+b+c}`,{js:`${a}+${b}+${c}`})}]);
T("dilate-geo","gcong","G.SRT.1","Dilations from any center",["dilate"],
 "A dilation with center C and scale factor k moves every point P to P' on ray CP with CP' = k·CP. If k is negative, the image is on the opposite side of the center.",
 ["Dilation about (h, k₀) with scale factor r: (x, y) → (h + r(x − h), k₀ + r(y − k₀)).","Lengths are multiplied by |r|; angles are unchanged; lines map to parallel lines.","Scale factor = image length ÷ original length."],
 [()=>{const h=ri(-4,4),k=ri(-4,4),r=ri(2,4),a=ri(-6,6),b=ri(-6,6);return mk("pair",`Dilate the point (${a}, ${b}) by scale factor ${r} with center (${h}, ${k}).`,`(${h+r*(a-h)}, ${k+r*(b-k)})`,"New point = center + scale × (point − center).",`(${h} + ${r}(${a-h}), ${k} + ${r}(${b-k})) = (${h+r*(a-h)}, ${k+r*(b-k)})`,{eqs:[`x-(${h})=${r}*((${a})-(${h}))`,`y-(${k})=${r}*((${b})-(${k}))`]})},
  ()=>{const q=pick([2,3]),h=ri(-4,4),k=ri(-4,4),a=h+q*ri(-4,4),b=k+q*ri(-4,4);return mk("pair",`Dilate the point (${a}, ${b}) by scale factor 1/${q} with center (${h}, ${k}).`,`(${h+(a-h)/q}, ${k+(b-k)/q})`,"New point = center + scale × (point − center).",`(${h} + (${a-h})/${q}, ${k} + (${b-k})/${q}) = (${h+(a-h)/q}, ${k+(b-k)/q})`,{eqs:[`${q}*(x-(${h}))=(${a})-(${h})`,`${q}*(y-(${k}))=(${b})-(${k})`]})},
  ()=>{const r=-ri(1,3),a=ri(-6,6),b=ri(-6,6);return mk("pair",`Dilate the point (${a}, ${b}) by scale factor ${r} with center at the origin.`,`(${r*a}, ${r*b})`,"A negative scale factor sends the point to the opposite side of the center.",`(${r}·${P(a)}, ${r}·${P(b)}) = (${r*a}, ${r*b})`,{eqs:[`x=(${r})*(${a})`,`y=(${r})*(${b})`]})},
  ()=>{const m=ri(2,6),p=ri(2,7);let q;do{q=ri(2,7)}while(gcd(p,q)!==1||p===q);const len=m*p,img=m*q;return mk("num",`A segment of length ${len} is dilated to a segment of length ${img}. What is the scale factor?`,q/p,"Scale factor = image length ÷ original length.",`${img} ÷ ${len} = ${q}/${p}`,{js:`${img}/${len}`})},
  ()=>{const x=ri(2,9),y=ri(2,9),k=pick([2,3,4]);return mk("num",`The dilation with center at the origin maps (${x}, ${y}) to (${k*x}, ${k*y}). What is the scale factor?`,k,"Divide an image coordinate by the matching original coordinate.",`${k*x} ÷ ${x} = ${k}`,{js:`${k*x}/${x}`})}]);

// ---------------- unit gsim ----------------
T("sim-tri","gsim","G.SRT.2","Similar triangles & proportions",["prop-solve","dilate-geo"],
 "Similar triangles have equal corresponding angles and proportional corresponding sides. The scale factor is the ratio of any pair of corresponding sides.",
 ["△ABC ∼ △DEF means AB/DE = BC/EF = AC/DF = scale factor.","Perimeters scale by k; areas scale by k²; angles do not change.","Set up a proportion, cross-multiply, and solve. Indirect measurement (shadows) works the same way."],
 [()=>{const m=ri(1,4),p=ri(2,5);let q;do{q=ri(2,6)}while(q===p);const n=ri(2,6);const ab=m*p,de=m*q,bc=n*p,ef=n*q;return mk("num",`△ABC ∼ △DEF with AB = ${ab}, DE = ${de} and BC = ${bc}. Find EF.`,ef,"Corresponding sides are proportional: AB/DE = BC/EF.",`${ab}/${de} = ${bc}/EF → EF = ${bc}·${de}/${ab} = ${ef}`,{js:`${bc}*${de}/${ab}`,eqs:[`${ab}*x=${bc}*${de}`]})},
  ()=>{let p,q;do{p=ri(2,12);q=ri(2,12)}while(gcd(p,q)!==1||p===q);const m=ri(1,3);return mk("num",`△ABC ∼ △DEF, with AB = ${p*m} and DE = ${q*m}. What is the ratio of the side lengths of △ABC to △DEF? (Give it as a fraction.)`,p/q,"Scale factor = corresponding side of ABC ÷ corresponding side of DEF.",`${p*m}/${q*m} = ${p}/${q}`,{js:`${p*m}/${q*m}`})},
  ()=>{const p=ri(2,5);let q;do{q=ri(p+1,p+4)}while(gcd(p,q)!==1);const n=ri(2,6),m=n*q,mm=ri(1,6);return mk("num",`△ABC ∼ △DEF with scale factor ${p} : ${q} (ABC : DEF). AB = x + ${mm} and DE = ${m}. Find x.`,p*n-mm,"AB/DE = p/q, so AB = p·DE/q.",`AB = ${p}(${m})/${q} = ${p*n}; x + ${mm} = ${p*n} → x = ${p*n-mm}`,{js:`${p*n}-${mm}`,eqs:[`${q}*(x+${mm})=${p}*${m}`]})},
  ()=>{const a=ri(2,5);let b;do{b=ri(2,7)}while(b===a||gcd(a,b)!==1);const P1=a*ri(3,9);return mk("num",`Two similar triangles have corresponding sides in the ratio ${a} : ${b}. The perimeter of the first is ${P1}. What is the perimeter of the second?`,P1*b/a,"Perimeters have the same ratio as the sides.",`${P1}·${b}/${a} = ${P1*b/a}`,{js:`${P1}*${b}/${a}`})},
  ()=>{const a=ri(2,4);let b;do{b=ri(2,6)}while(b===a||gcd(a,b)!==1);const A1=a*a*ri(1,5);return mk("num",`Two similar triangles have corresponding sides in the ratio ${a} : ${b}. The area of the first is ${A1}. What is the area of the second?`,A1*b*b/(a*a),"Areas scale by the square of the side ratio.",`${A1}·(${b}/${a})² = ${A1*b*b/(a*a)}`,{js:`${A1}*${b}**2/${a}**2`})},
  ()=>{const h=ri(4,7)*10,s=ri(2,5)*10,k=ri(2,6);const t=s*k;const H=h*k;return mk("num",`A ${h}-cm stick casts a ${s}-cm shadow at the same time a tree casts a ${t}-cm shadow. How tall is the tree in cm?`,H,"The sun makes similar right triangles: height/shadow is the same for both.",`${h}/${s} = H/${t} → H = ${h}·${t}/${s} = ${H}`,{js:`${h}*${t}/${s}`})}]);
T("sim-crit","gsim","G.SRT.3","Similarity criteria: AA, SAS~, SSS~",["sim-tri","tri-ang-sum"],
 "To prove triangles similar you do not need all six parts. Two equal angles (AA), two proportional sides with an equal included angle (SAS~), or three proportional sides (SSS~) are enough.",
 ["AA: two pairs of equal angles (the third pair then matches automatically).","SAS~: two pairs of proportional sides and the included angles equal.","SSS~: all three pairs of sides have the same ratio. Compare the sorted side lengths."],
 [()=>{const A1=ri(30,80),B1=ri(30,80),C1=180-A1-B1;if(C1<20)return null;const [A,B,C,D,E,F]=pick(GTRI);return mcq(`In △${A}${B}${C}, m∠${A} = ${A1}° and m∠${B} = ${B1}°. In △${D}${E}${F}, m∠${D} = ${A1}° and m∠${F} = ${C1}°. Which statement is true?`,`△${A}${B}${C} ∼ △${D}${E}${F} by AA`,[`The triangles are not similar`,`△${A}${B}${C} ≅ △${D}${E}${F} by ASA`,`△${A}${B}${C} ∼ △${D}${E}${F} by SSS~`],"Find the third angle of each triangle and compare.",`m∠${C} = 180 − ${A1} − ${B1} = ${C1}°. Then ∠${A}≅∠${D} and ∠${C}≅∠${F}: AA.`)},
  ()=>{const s=sorted=>sorted.slice().sort((x,y)=>x-y);let a,b,c;do{a=ri(3,9);b=ri(a,12);c=ri(b,15)}while(a+b<=c);const k=pick([2,3,1.5]);const [a2,b2,c2]=[a*k,b*k,c*k];if(![a2,b2,c2].every(Number.isInteger))return null;
   const same=Math.random()<0.5;const t=same?[a2,b2,c2]:[a2,b2,c2+1];const sim=same;
   return mcq(`Triangle 1 has sides ${a}, ${b}, ${c}. Triangle 2 has sides ${t.join(", ")}. Are the triangles similar?`,sim?"Yes, by SSS~":"No",sim?["No","Yes, by AA"]:["Yes, by SSS~","Yes, by AA"],"Compare the ratios of the sorted side lengths.",sim?`${t[0]}/${a} = ${t[1]}/${b} = ${t[2]}/${c} = ${k}`:`${t[0]}/${a} = ${t[1]}/${b} = ${k}, but ${t[2]}/${c} ≠ ${k}.`)},
  ()=>{const A1=ri(30,80),B1=ri(30,80);if(A1+B1>150)return null;const [A,B,C,D,E,F]=pick(GTRI);return mk("num",`△${A}${B}${C} ∼ △${D}${E}${F}. m∠${A} = ${A1}° and m∠${E} = ${B1}°. Find m∠${C}.`,180-A1-B1,"Corresponding angles are equal: ∠B = ∠E, so ∠A and ∠B are known.",`m∠${B} = ${B1}°, so m∠${C} = 180 − ${A1} − ${B1} = ${180-A1-B1}°`,{js:`180-${A1}-${B1}`})},
  ()=>{const a=ri(2,8),b=ri(2,8),k=pick([2,3,4]),ang=ri(30,120);const same=Math.random()<0.5;const b2=same?k*b:k*b+1;
   const [A,B,C,D,E,F]=pick(GTRI);return mcq(`In △${A}${B}${C}: ${A}${B} = ${a}, ${A}${C} = ${b}, m∠${A} = ${ang}°. In △${D}${E}${F}: ${D}${E} = ${k*a}, ${D}${F} = ${b2}, m∠${D} = ${ang}°. Are the triangles similar?`,same?"Yes, by SAS~":"No",same?["No","Yes, by AA"]:["Yes, by SAS~","Yes, by AA"],"Check that both pairs of sides around the equal angle have the same ratio.",same?`${k*a}/${a} = ${k*b}/${b} = ${k} with the included angles equal: SAS~.`:`${k*a}/${a} = ${k}, but ${b2}/${b} ≠ ${k}, so the sides are not proportional.`)}].map(gRetry));
T("par-prop","gsim","G.SRT.4","Triangle proportionality & the angle bisector theorem",["sim-tri"],
 "A line parallel to one side of a triangle splits the other two sides proportionally. An angle bisector splits the opposite side in the ratio of the adjacent sides.",
 ["If DE ∥ BC (D on AB, E on AC): AD/DB = AE/EC and AD/AB = AE/AC.","Angle bisector from A hits BC at D: BD/DC = AB/AC.","Cross-multiply and solve."],
 [()=>{const m=ri(1,4),p=ri(2,5),q=ri(2,6),n=ri(1,4);const AD=m*p,DB=m*q,AE=n*p,EC=n*q;return mk("num",`In △ABC, DE ∥ BC with D on AB and E on AC. AD = ${AD}, DB = ${DB} and AE = ${AE}. Find EC.`,EC,"The parallel line cuts the sides proportionally: AD/DB = AE/EC.",`${AD}/${DB} = ${AE}/EC → EC = ${AE}·${DB}/${AD} = ${EC}`,{js:`${AE}*${DB}/${AD}`,eqs:[`${AD}*x=${AE}*${DB}`]})},
  ()=>{const p=ri(2,5),q=ri(1,5),m=ri(1,3),n=ri(1,4);const AD=p*m,AB=(p+q)*m,AE=p*n,AC=(p+q)*n;return mk("num",`In △ABC, DE ∥ BC with D on AB and E on AC. AD = ${AD}, AB = ${AB} and AE = ${AE}. Find AC.`,AC,"AD/AB = AE/AC.",`${AD}/${AB} = ${AE}/AC → AC = ${AE}·${AB}/${AD} = ${AC}`,{js:`${AE}*${AB}/${AD}`,eqs:[`${AD}*x=${AE}*${AB}`]})},
  ()=>{const m=ri(2,6),n=ri(2,8),pp=ri(2,6);const x=m*n;if(x%pp)return null;const X=x/pp;return mk("num",`In △ABC, DE ∥ BC. AD = x, DB = ${m}, AE = ${n} and EC = ${pp}. Find x.`,X,"AD/DB = AE/EC.",`x/${m} = ${n}/${pp} → x = ${m}·${n}/${pp} = ${X}`,{js:`${m}*${n}/${pp}`,eqs:[`x*${pp}=${m}*${n}`]})},
  ()=>{const p=ri(2,6),q=ri(2,6);if(p===q)return null;const m=ri(1,5);const BD=p*m,DC=q*m,AB=p*ri(1,4),AC=q*(AB/p);return mk("num",`In △ABC, AD bisects ∠A with D on BC. AB = ${AB}, AC = ${AC} and BD = ${BD}. Find DC.`,DC,"Angle bisector theorem: BD/DC = AB/AC.",`${BD}/DC = ${AB}/${AC} → DC = ${BD}·${AC}/${AB} = ${DC}`,{js:`${BD}*${AC}/${AB}`,eqs:[`${BD}*${AC}=x*${AB}`]})}].map(gRetry));
T("geo-mean","gsim","G.SRT.8","Altitude to the hypotenuse & geometric means",["sim-tri","pyth","sqrt-basic"],
 "In a right triangle, the altitude to the hypotenuse creates two smaller triangles similar to the original and to each other. This produces three geometric-mean relationships.",
 ["Altitude: h² = p·q, where p and q are the pieces of the hypotenuse.","Leg: a² = p·c, where c = p + q is the whole hypotenuse and p is the piece adjacent to leg a.","Simplify radicals: √48 = 4√3."],
 [()=>{const a=ri(1,6),s=ri(1,4),t=ri(1,4);if(s===t)return null;const p=a*s*s,q=a*t*t;return mk("num",`The altitude to the hypotenuse of a right triangle divides the hypotenuse into segments of length ${p} and ${q}. Find the length of the altitude.`,a*s*t,"Altitude = √(p·q) (geometric mean of the two segments).",`√(${p}·${q}) = √${p*q} = ${a*s*t}`,{js:`Math.sqrt(${p}*${q})`})},
  ()=>{let p,q;do{p=ri(2,12);q=ri(2,12)}while(p===q||SQ(p*q));return mk("expr",`The altitude to the hypotenuse of a right triangle divides the hypotenuse into segments of length ${p} and ${q}. Find the altitude as a simplified radical.`,radStr(p*q),"h = √(p·q), then simplify.",`√(${p}·${q}) = √${p*q} = ${radStr(p*q).replace(/sqrt\((\d+)\)/,"√$1")}`,{form:"rad",pe:`Math.sqrt(${p*q})`})},
  ()=>{let p,q;do{p=ri(2,9);q=ri(2,9)}while(p===q||SQ(p*(p+q)));return mk("expr",`In a right triangle the altitude to the hypotenuse splits the hypotenuse into pieces of length ${p} and ${q}. Find the length of the leg adjacent to the segment of length ${p}, as a simplified radical.`,radStr(p*(p+q)),"leg² = (adjacent piece)(whole hypotenuse).",`leg² = ${p}·${p+q} = ${p*(p+q)}; leg = ${radStr(p*(p+q)).replace(/sqrt\((\d+)\)/,"√$1")}`,{form:"rad",pe:`Math.sqrt(${p}*(${p}+${q}))`})},
  ()=>{const h=ri(2,12),p=ri(1,6)*1;if((h*h)%p)return null;const q=h*h/p;return mk("num",`The altitude to the hypotenuse of a right triangle is ${h}. It splits the hypotenuse into two pieces, one of length ${p}. Find the other piece.`,q,"h² = p·q, so q = h²/p.",`${h}² ÷ ${p} = ${q}`,{js:`${h}**2/${p}`})},
  ()=>{const p=ri(2,9),q=ri(1,9),c=p+q;const a2=p*c;if(!SQ(a2))return null;return mk("num",`In a right triangle the hypotenuse is ${c} and the altitude to it splits it into pieces ${p} and ${q}. Find the leg adjacent to the piece of length ${p}.`,Math.sqrt(a2),"leg² = (adjacent piece) × (hypotenuse).",`√(${p}·${c}) = √${a2} = ${Math.sqrt(a2)}`,{js:`Math.sqrt(${p}*${p+q})`})}].map(gRetry));

// ---------------- unit gtrig ----------------
const gfr=(a,b)=>{const g=gcd(Math.abs(a),Math.abs(b));return b/g===1?String(a/g):`${a/g}/${b/g}`};
const gsin=t=>Math.sin(t*Math.PI/180),gcos=t=>Math.cos(t*Math.PI/180),gtan=t=>Math.tan(t*Math.PI/180);
const GTT=TRI.slice(0,6);
T("trig-ratios","gtrig","G.SRT.6","Sine, cosine & tangent ratios",["pyth","sim-tri"],
 "In similar right triangles the ratios of corresponding sides are equal. Those fixed ratios, which depend only on the acute angle, are called sine, cosine and tangent.",
 ["SOH-CAH-TOA: sin = opposite/hypotenuse, cos = adjacent/hypotenuse, tan = opposite/adjacent (relative to the angle you are using).","The hypotenuse is opposite the right angle; opposite and adjacent switch when you switch angles.","Reduce ratios to lowest terms; use the Pythagorean theorem if one side is missing."],
 [()=>{const [a,b,c]=pick(GTT),k=ri(1,3);const f=pick(["sin","cos","tan"]);const num={sin:a,cos:b,tan:a}[f]*k,den={sin:c,cos:c,tan:b}[f]*k;
   return mk("num",`In right triangle ABC the right angle is at C, AC = ${b*k}, BC = ${a*k} and AB = ${c*k}. Find ${f} A as a fraction in lowest terms.`,gfr(num,den),"sin = opp/hyp, cos = adj/hyp, tan = opp/adj, where opposite/adjacent refer to ∠A.",`Opposite A is BC = ${a*k}, adjacent is AC = ${b*k}, hypotenuse is AB = ${c*k}: ${f} A = ${num}/${den} = ${gfr(num,den)}`,{js:`${num}/${den}`})},
  ()=>{const [a,b,c]=pick(GTT),k=ri(1,3);const f=pick(["sin","cos","tan"]);const num={sin:b,cos:a,tan:b}[f]*k,den={sin:c,cos:c,tan:a}[f]*k;
   return mk("num",`In right triangle ABC the right angle is at C, AC = ${b*k}, BC = ${a*k} and AB = ${c*k}. Find ${f} B as a fraction in lowest terms.`,gfr(num,den),"For ∠B: opposite is AC, adjacent is BC.",`${f} B = ${num}/${den} = ${gfr(num,den)}`,{js:`${num}/${den}`})},
  ()=>{const [a,b,c]=pick(GTT),k=ri(1,3);const f=pick(["sin","cos","tan"]),ang=pick(["A","B"]);const o=ang==="A"?a:b,ad=ang==="A"?b:a;const num={sin:o,cos:ad,tan:o}[f]*k,den={sin:c,cos:c,tan:ad}[f]*k;
   const side=ang==="A"?["BC","AC"]:["AC","BC"];
   return mk("num",`In right triangle ABC (right angle at C) the hypotenuse is AB = ${c*k} and ${side[0]} = ${o*k}. Find ${f} ${ang} as a fraction in lowest terms. (Find ${side[1]} first.)`,gfr(num,den),"Find the missing leg with the Pythagorean theorem, then use SOH-CAH-TOA.",`${side[1]} = √(${c*k}² − ${o*k}²) = ${ad*k}. ${f} ${ang} = ${num}/${den} = ${gfr(num,den)}`,{js:`${num}/${den}`})},
  ()=>{const [a,b,c]=pick(GTT);const f=pick(["sin","cos","tan"]);const sid={sin:`${a}/${c}`,cos:`${b}/${c}`,tan:`${a}/${b}`}[f];const other={sin:"cos",cos:"sin",tan:"tan"}[f];
   if(f==="tan")return null;const ans=other==="cos"?gfr(b,c):gfr(a,c);
   return mk("num",`In a right triangle, ∠A is acute and ${f} A = ${gfr(f==="sin"?a:b,c)}. Find ${other} A in lowest terms.`,ans,"Draw a right triangle with those two sides, find the third side with the Pythagorean theorem, then read off the other ratio.",`Sides ${a}, ${b}, ${c} (in this ratio) → ${other} A = ${ans}`,{js:`${other==="cos"?b:a}/${c}`})},
  ()=>{const f=pick(["sin","cos","tan"]);const ans={sin:"opposite ÷ hypotenuse",cos:"adjacent ÷ hypotenuse",tan:"opposite ÷ adjacent"}[f];return mcq(`In a right triangle, which ratio defines ${f} of an acute angle?`,ans,["opposite ÷ hypotenuse","adjacent ÷ hypotenuse","opposite ÷ adjacent","hypotenuse ÷ opposite"].filter(x=>x!==ans).slice(0,3),"SOH-CAH-TOA.",`${f} = ${ans}`)}].map(gRetry));
T("trig-solve","gtrig","G.SRT.8","Finding side lengths with trigonometry",["trig-ratios"],
 "If you know one acute angle and one side of a right triangle, a trig ratio gives any other side. Choose the ratio that connects the side you know with the side you want.",
 ["Pick the ratio: opposite & hypotenuse → sin; adjacent & hypotenuse → cos; opposite & adjacent → tan.","Unknown in the numerator: multiply. Unknown in the denominator: divide.","Use degree mode on your calculator and round at the end."],
 [()=>{const t=ri(20,70),c=ri(8,60);const v=c*gsin(t);if(!gok(v))return null;return mk("num",`In a right triangle, an acute angle measures ${t}° and the hypotenuse is ${c}. Find the length of the side opposite the ${t}° angle. Round to the nearest tenth.`,rdn(v,1),"sin θ = opposite/hypotenuse.",`opposite = ${c}·sin ${t}° ≈ ${rdn(v,1)}`,{js:`${c}*Math.sin(${t}*Math.PI/180)`,jtol:0.051})},
  ()=>{const t=ri(20,70),c=ri(8,60);const v=c*gcos(t);if(!gok(v))return null;return mk("num",`In a right triangle, an acute angle measures ${t}° and the hypotenuse is ${c}. Find the length of the side adjacent to the ${t}° angle. Round to the nearest tenth.`,rdn(v,1),"cos θ = adjacent/hypotenuse.",`adjacent = ${c}·cos ${t}° ≈ ${rdn(v,1)}`,{js:`${c}*Math.cos(${t}*Math.PI/180)`,jtol:0.051})},
  ()=>{const t=ri(20,70),a=ri(6,40);const v=a*gtan(t);if(!gok(v))return null;return mk("num",`In a right triangle, an acute angle measures ${t}° and the adjacent leg is ${a}. Find the length of the opposite leg. Round to the nearest tenth.`,rdn(v,1),"tan θ = opposite/adjacent.",`opposite = ${a}·tan ${t}° ≈ ${rdn(v,1)}`,{js:`${a}*Math.tan(${t}*Math.PI/180)`,jtol:0.051})},
  ()=>{const t=ri(20,70),o=ri(6,40);const v=o/gsin(t);if(!gok(v))return null;return mk("num",`In a right triangle, an acute angle measures ${t}° and the side opposite it is ${o}. Find the hypotenuse. Round to the nearest tenth.`,rdn(v,1),"sin θ = opposite/hypotenuse, so hypotenuse = opposite ÷ sin θ.",`hypotenuse = ${o} ÷ sin ${t}° ≈ ${rdn(v,1)}`,{js:`${o}/Math.sin(${t}*Math.PI/180)`,jtol:0.051})},
  ()=>{const t=ri(20,70),o=ri(6,40);const v=o/gtan(t);if(!gok(v))return null;return mk("num",`In a right triangle, an acute angle measures ${t}° and the side opposite it is ${o}. Find the length of the leg adjacent to the angle. Round to the nearest tenth.`,rdn(v,1),"tan θ = opposite/adjacent, so adjacent = opposite ÷ tan θ.",`adjacent = ${o} ÷ tan ${t}° ≈ ${rdn(v,1)}`,{js:`${o}/Math.tan(${t}*Math.PI/180)`,jtol:0.051})}].map(gRetry));
T("trig-angle","gtrig","G.SRT.8","Finding angles with inverse trigonometry",["trig-solve"],
 "When you know two sides of a right triangle, an inverse trig function (sin⁻¹, cos⁻¹, tan⁻¹) returns the acute angle.",
 ["Choose the ratio from the two sides you know, then apply the inverse: θ = tan⁻¹(opp/adj), sin⁻¹(opp/hyp), cos⁻¹(adj/hyp).","The two acute angles add to 90°.","Use degree mode and round only at the end."],
 [()=>{let o,a;do{o=ri(3,30);a=ri(3,30)}while(o===a);const v=Math.atan(o/a)*180/Math.PI;if(!gok(v))return null;return mk("num",`In a right triangle the legs are ${o} (opposite ∠A) and ${a} (adjacent to ∠A). Find m∠A to the nearest tenth of a degree.`,rdn(v,1),"tan A = opposite/adjacent, so A = tan⁻¹(opp/adj).",`A = tan⁻¹(${o}/${a}) ≈ ${rdn(v,1)}°`,{js:`Math.atan(${o}/${a})*180/Math.PI`,jtol:0.051})},
  ()=>{let o,h;do{h=ri(6,40);o=ri(2,h-1)}while(false);const v=Math.asin(o/h)*180/Math.PI;if(!gok(v))return null;return mk("num",`In a right triangle the hypotenuse is ${h} and the side opposite ∠A is ${o}. Find m∠A to the nearest tenth of a degree.`,rdn(v,1),"sin A = opposite/hypotenuse, so A = sin⁻¹(opp/hyp).",`A = sin⁻¹(${o}/${h}) ≈ ${rdn(v,1)}°`,{js:`Math.asin(${o}/${h})*180/Math.PI`,jtol:0.051})},
  ()=>{let a,h;do{h=ri(6,40);a=ri(2,h-1)}while(false);const v=Math.acos(a/h)*180/Math.PI;if(!gok(v))return null;return mk("num",`A ${h}-foot ladder leans against a wall with its base ${a} feet from the wall. What angle does the ladder make with the ground, to the nearest tenth of a degree?`,rdn(v,1),"The base distance is adjacent to the angle at the ground and the ladder is the hypotenuse: cos θ = adjacent/hypotenuse.",`θ = cos⁻¹(${a}/${h}) ≈ ${rdn(v,1)}°`,{js:`Math.acos(${a}/${h})*180/Math.PI`,jtol:0.051})},
  ()=>{let o,a;do{o=ri(3,30);a=ri(3,30)}while(o===a);const v=90-Math.atan(o/a)*180/Math.PI;if(!gok(v))return null;return mk("num",`In right triangle ABC (right angle at C), BC = ${o} and AC = ${a}. Find m∠B to the nearest tenth of a degree.`,rdn(v,1),"For ∠B the opposite side is AC and the adjacent side is BC: tan B = AC/BC.",`B = tan⁻¹(${a}/${o}) ≈ ${rdn(v,1)}°`,{js:`Math.atan(${a}/${o})*180/Math.PI`,jtol:0.051})}].map(gRetry));
T("special-rt","gtrig","G.SRT.6","Special right triangles (45-45-90 and 30-60-90)",["trig-ratios","rad-simp"],
 "Two right triangles have side ratios you can write exactly: the isosceles right triangle (45°-45°-90°) and half of an equilateral triangle (30°-60°-90°).",
 ["45°-45°-90°: legs x, x, hypotenuse x√2.","30°-60°-90°: short leg x (opposite 30°), long leg x√3 (opposite 60°), hypotenuse 2x.","Find the short leg (or the leg) first, then multiply to get the others."],
 [()=>{const L=ri(2,15);return mk("expr",`A 45°-45°-90° triangle has legs of length ${L}. Find the hypotenuse.`,`${L}sqrt(2)`,"Hypotenuse = leg × √2.",`${L}√2`,{form:"rad",pe:`${L}*Math.SQRT2`})},
  ()=>{const L=ri(2,15);return mk("num",`The hypotenuse of a 45°-45°-90° triangle is ${L}√2. Find the length of a leg.`,L,"Leg = hypotenuse ÷ √2.",`${L}√2 ÷ √2 = ${L}`,{js:`${L}*Math.SQRT2/Math.SQRT2`})},
  ()=>{const s=ri(2,15);return mk("expr",`In a 30°-60°-90° triangle the shorter leg is ${s}. Find the longer leg.`,`${s}sqrt(3)`,"Long leg = short leg × √3.",`${s}√3`,{form:"rad",pe:`${s}*Math.sqrt(3)`})},
  ()=>{const s=ri(2,20);return mk("num",`In a 30°-60°-90° triangle the hypotenuse is ${2*s}. Find the shorter leg.`,s,"Short leg = hypotenuse ÷ 2.",`${2*s} ÷ 2 = ${s}`,{js:`${2*s}/2`})},
  ()=>{const s=ri(2,15);return mk("num",`In a 30°-60°-90° triangle the longer leg is ${s}√3. Find the hypotenuse.`,2*s,"Long leg = short leg × √3, so short = long ÷ √3 and hypotenuse = 2 × short.",`short leg = ${s}; hypotenuse = ${2*s}`,{js:`2*${s}*Math.sqrt(3)/Math.sqrt(3)`})},
  ()=>{const k=ri(2,10);return mk("expr",`The hypotenuse of a 45°-45°-90° triangle is ${2*k}. Find the length of a leg as a simplified radical.`,`${k}sqrt(2)`,"Leg = hypotenuse ÷ √2 = hypotenuse·√2/2.",`${2*k}/√2 = ${2*k}√2/2 = ${k}√2`,{form:"rad",pe:`${2*k}/Math.SQRT2`})}]);
T("trig-apps","gtrig","G.SRT.8","Angles of elevation & depression; applications",["trig-angle","special-rt"],
 "Real problems give a right triangle in disguise. The angle of elevation is measured up from the horizontal; the angle of depression down from the horizontal; the two are equal (alternate interior angles).",
 ["Draw and label the right triangle first: the horizontal line, the line of sight, and the vertical side.","Choose sin, cos or tan from the sides involved, then solve.","Include the observer's height if needed, and round only at the end."],
 [()=>{const d=ri(20,120),t=ri(20,65);const v=d*gtan(t);if(!gok(v))return null;return mk("num",`From a point ${d} feet from the base of a tower, the angle of elevation to the top is ${t}°. How tall is the tower, to the nearest tenth of a foot?`,rdn(v,1),"tan θ = height/distance.",`height = ${d}·tan ${t}° ≈ ${rdn(v,1)}`,{js:`${d}*Math.tan(${t}*Math.PI/180)`,jtol:0.051})},
  ()=>{const h=ri(30,150),d=ri(30,150);const v=Math.atan(h/d)*180/Math.PI;if(!gok(v))return null;return mk("num",`From the top of a ${h}-foot cliff, a boat is ${d} feet from the base of the cliff. What is the angle of depression to the boat, to the nearest tenth of a degree?`,rdn(v,1),"The angle of depression equals the angle of elevation from the boat: tan θ = height/distance.",`θ = tan⁻¹(${h}/${d}) ≈ ${rdn(v,1)}°`,{js:`Math.atan(${h}/${d})*180/Math.PI`,jtol:0.051})},
  ()=>{const L=ri(10,40),t=ri(55,80);const v=L*gsin(t);if(!gok(v))return null;return mk("num",`A ${L}-foot ladder makes an angle of ${t}° with the ground. How high up the wall does it reach, to the nearest tenth of a foot?`,rdn(v,1),"sin θ = height/ladder length.",`height = ${L}·sin ${t}° ≈ ${rdn(v,1)}`,{js:`${L}*Math.sin(${t}*Math.PI/180)`,jtol:0.051})},
  ()=>{const h=ri(5,30),t=ri(20,60);const v=h/gsin(t);if(!gok(v))return null;return mk("num",`A wheelchair ramp must rise ${h} inches at an angle of ${t}° with the ground. How long is the ramp, to the nearest tenth of an inch?`,rdn(v,1),"sin θ = rise/ramp length, so length = rise ÷ sin θ.",`length = ${h} ÷ sin ${t}° ≈ ${rdn(v,1)}`,{js:`${h}/Math.sin(${t}*Math.PI/180)`,jtol:0.051})},
  ()=>{const e=ri(3,6)*10+ri(0,1)*5,d=ri(40,150),h=ri(4,6);const hh=h;const v=d*gtan(e)+hh;if(!gok(v))return null;return mk("num",`A person whose eyes are ${hh} feet above the ground stands ${d} feet from a flagpole and sees its top at an angle of elevation of ${e}°. How tall is the flagpole, to the nearest tenth of a foot?`,rdn(v,1),"The part above eye level is d·tan θ; add the eye height.",`${d}·tan ${e}° + ${hh} ≈ ${rdn(v,1)}`,{js:`${d}*Math.tan(${e}*Math.PI/180)+${hh}`,jtol:0.051})}].map(gRetry));
T("cofunc","gtrig","G.SRT.7","Complementary angles: sine & cosine",["trig-ratios","seg-add"],
 "The sine of an angle equals the cosine of its complement: sin θ = cos(90° − θ). This is because the opposite side of one acute angle is the adjacent side of the other.",
 ["sin A = cos B and cos A = sin B when A + B = 90°.","If sin(u) = cos(v) for acute angles, then u + v = 90°.","tan A = 1 / tan B when A and B are complementary."],
 [()=>{const t=ri(5,85);const f=pick(["sin","cos"]);const g=f==="sin"?"cos":"sin";return mk("num",`If ${f} ${t}° = ${g} θ, where θ is acute, find θ.`,90-t,"Complementary angles: sin θ = cos(90° − θ).",`θ = 90 − ${t} = ${90-t}°`,{js:`90-${t}`})},
  ()=>{const a=ri(1,4),b=ri(1,4),x=ri(2,12),p=ri(1,10);const q=90-(a+b)*x-p;if(q<1)return null;return mk("num",`sin(${lin(a,p)})° = cos(${lin(b,q)})°, where both angles are acute. Find x.`,x,"The angles are complementary, so they sum to 90°.",`${lin(a,p)} + ${lin(b,q)} = 90 → ${a+b}x = ${90-p-q} → x = ${x}`,{js:`${x}`,eqs:[`(${a})*x+${p}+(${b})*x+${q}=90`]})},
  ()=>{const [a,b,c]=pick(GTT);const f=pick(["sin","cos"]);const g=f==="sin"?"cos":"sin";const num=f==="sin"?a:b;return mk("num",`In right triangle ABC with the right angle at C, ${f} A = ${gfr(num,c)}. Find ${g} B.`,gfr(num,c),`In a right triangle the acute angles are complementary, so ${f} A = ${g} B.`,`${g} B = ${f} A = ${gfr(num,c)}`,{js:`${num}/${c}`})},
  ()=>{const [a,b,c]=pick(GTT);return mk("num",`In right triangle ABC with the right angle at C, tan A = ${gfr(a,b)}. Find tan B.`,gfr(b,a),"tan B = 1 / tan A for complementary angles (opposite and adjacent swap).",`tan B = ${b}/${a} = ${gfr(b,a)}`,{js:`${b}/${a}`})}].map(gRetry));

// ---------------- unit gcirc ----------------
T("circ-arcs","gcirc","G.C.2","Central & inscribed angles, arcs",["tri-ang-sum","circle-basic"],
 "Angles in a circle are tied to the arcs they cut off. A central angle equals its arc; an inscribed angle is half its intercepted arc.",
 ["Central angle = intercepted arc.  Inscribed angle = ½ intercepted arc. An angle inscribed in a semicircle is 90°.","Two chords meeting inside: angle = ½(arc + vertical arc).  Secants/tangents meeting outside: angle = ½(far arc − near arc).","A cyclic quadrilateral has supplementary opposite angles. Tangent–chord angle = ½ intercepted arc."],
 [()=>{const arc=2*ri(10,85);if(Math.random()<0.5)return mk("num",`An inscribed angle intercepts an arc of ${arc}°. Find the measure of the inscribed angle.`,arc/2,"Inscribed angle = ½ intercepted arc.",`${arc} ÷ 2 = ${arc/2}°`,{js:`${arc}/2`});
   return mk("num",`An inscribed angle measures ${arc/2}°. Find the measure of its intercepted arc.`,arc,"Intercepted arc = 2 × inscribed angle.",`2 × ${arc/2} = ${arc}°`,{js:`2*${arc/2}`})},
  ()=>{const a=2*ri(10,70),b=2*ri(10,70);return mk("num",`Two chords intersect inside a circle. The two arcs intercepted by the angle and its vertical angle measure ${a}° and ${b}°. Find the measure of the angle.`,(a+b)/2,"Angle inside = ½(sum of the intercepted arcs).",`(${a} + ${b}) ÷ 2 = ${(a+b)/2}°`,{js:`(${a}+${b})/2`})},
  ()=>{const far=ri(60,170),near=ri(15,far-20);const e=far-near;if(e%2)return null;return mk("num",`Two secants meet outside a circle. They intercept a far arc of ${far}° and a near arc of ${near}°. Find the angle between the secants.`,e/2,"Angle outside = ½(far arc − near arc).",`(${far} − ${near}) ÷ 2 = ${e/2}°`,{js:`(${far}-${near})/2`})},
  ()=>{const x=ri(25,65);return mk("num",`AB is a diameter of a circle and C is another point on the circle. If m∠CAB = ${x}°, find m∠CBA.`,90-x,"∠ACB is inscribed in a semicircle, so it is 90°; the other two angles sum to 90°.",`180 − 90 − ${x} = ${90-x}°`,{js:`180-90-${x}`})},
  ()=>{const arc=2*ri(20,80);return mk("num",`A tangent and a chord meet at a point on a circle and intercept an arc of ${arc}°. Find the angle between the tangent and the chord.`,arc/2,"Tangent–chord angle = ½ intercepted arc.",`${arc} ÷ 2 = ${arc/2}°`,{js:`${arc}/2`})},
  ()=>{let a,c,x,b,d;do{a=ri(1,4);c=ri(1,4);x=ri(5,20);b=ri(1,30);d=180-(a+c)*x-b}while(d<1);const ans=a*x+b;return mk("num",`Opposite angles of a quadrilateral inscribed in a circle measure (${lin(a,b)})° and (${lin(c,d)})°. Find the measure of the first angle.`,ans,"Opposite angles of a cyclic quadrilateral are supplementary.",`${lin(a,b)} + ${lin(c,d)} = 180 → x = ${x}; angle = ${ans}°`,{js:`${a}*${x}+${b}`,eqs:[`(${a})*(${x})+${b}+(${c})*(${x})+${d}=180`]})}].map(gRetry));
T("circ-chords","gcirc","G.C.2","Chords, secants & tangents: lengths",["circ-arcs","sim-tri","pyth"],
 "Similar triangles inside circles give product rules for chords, secants and tangents. A tangent is perpendicular to the radius at the point of tangency.",
 ["Intersecting chords: (part)(part) = (part)(part).","Secant–secant: (outside)(whole) = (outside)(whole). Tangent–secant: (tangent)² = (outside)(whole).","Tangent ⟂ radius: use the Pythagorean theorem. Two tangents from one point are equal."],
 [()=>{const a=ri(2,9),b=ri(2,9),c=ri(2,6);if((a*b)%c)return null;const d=a*b/c;return mk("num",`Two chords intersect inside a circle. One chord is split into segments ${a} and ${b}; the other into segments ${c} and x. Find x.`,d,"Intersecting chords: product of the segments is equal.",`${a}·${b} = ${c}·x → x = ${a*b}/${c} = ${d}`,{js:`${a}*${b}/${c}`,eqs:[`${a}*${b}=${c}*x`]})},
  ()=>{const o1=ri(2,6),w1=o1+ri(2,8),o2=ri(2,6);if((o1*w1)%o2)return null;const w2=o1*w1/o2;if(w2<=o2)return null;return mk("num",`Two secants are drawn from an external point. The first has external part ${o1} and whole length ${w1}. The second has external part ${o2} and whole length x. Find x.`,w2,"Secant–secant: (outside)(whole) = (outside)(whole).",`${o1}·${w1} = ${o2}·x → x = ${w2}`,{js:`${o1}*${w1}/${o2}`,eqs:[`${o1}*${w1}=${o2}*x`]})},
  ()=>{const t=ri(3,12),o=ri(1,t*t);const f=[];for(let e=1;e<t*t;e++)if((t*t)%e===0&&e<t)f.push(e);const e=pick(f.length?f:[1]);const w=t*t/e;return mk("num",`A tangent from an external point has length ${t}. A secant from the same point has external part ${e} and whole length x. Find x.`,w,"Tangent–secant: (tangent)² = (outside)(whole).",`${t}² = ${e}·x → x = ${t*t}/${e} = ${w}`,{js:`${t}**2/${e}`,eqs:[`${t}**2=${e}*x`]})},
  ()=>{const [a,b,c]=pick(GTT),k=ri(1,3);return mk("num",`A tangent segment is drawn to a circle of radius ${a*k} from a point ${c*k} units from the center. Find the length of the tangent segment.`,b*k,"The radius is perpendicular to the tangent: radius² + tangent² = distance².",`√(${c*k}² − ${a*k}²) = ${b*k}`,{js:`Math.sqrt(${c*k}**2-${a*k}**2)`})},
  ()=>{const [a,b,c]=pick(GTT),k=ri(1,3);return mk("num",`In a circle of radius ${c*k}, a chord lies ${a*k} units from the center. Find the length of the chord.`,2*b*k,"The perpendicular from the center bisects the chord: half-chord = √(r² − d²).",`half = √(${c*k}² − ${a*k}²) = ${b*k}; chord = ${2*b*k}`,{js:`2*Math.sqrt(${c*k}**2-${a*k}**2)`})},
  ()=>{const {a,b,c,d,x}=gEq();return mk("num",`Two tangent segments are drawn to a circle from the same external point. Their lengths are ${lin(a,b)} and ${lin(c,d)}. Find the length of each tangent.`,a*x+b,"Tangent segments from one external point are equal.",`${lin(a,b)} = ${lin(c,d)} → x = ${x}; length = ${a*x+b}`,{js:`${a}*${x}+${b}`,eqs:[`(${a})*(${x})+${b}=(${c})*(${x})+${d}`]})}].map(gRetry));
const gpiStr=(n,d)=>{const g=gcd(Math.abs(n),d);n/=g;d/=g;return d===1?(n===1?"pi":n+"pi"):(n===1?"pi":n+"pi")+"/"+d};
T("arc-sector","gcirc","G.C.5","Arc length, sector area & radians",["circ-arcs","frac-muldiv"],
 "A central angle θ takes up the fraction θ/360° of a circle. Arc length and sector area are that same fraction of the circumference and area. A radian is the angle whose arc length equals the radius.",
 ["Arc length = (θ/360°)·2πr.  Sector area = (θ/360°)·πr².","π radians = 180°: multiply degrees by π/180 to get radians, radians by 180/π to get degrees.","In radians: arc length s = rθ and sector area = ½r²θ."],
 [()=>{const r=ri(2,15),t=pick([30,45,60,90,120,135,150,180,240,270]);return mk("expr",`Find the length of an arc with central angle ${t}° in a circle of radius ${r}. Leave your answer in terms of π.`,gpiStr(2*r*t,360),"Arc length = (θ/360)·2πr.",`(${t}/360)(2π·${r}) = ${gpiStr(2*r*t,360).replace("pi","π")}`,{pe:`${t}/360*2*Math.PI*${r}`})},
  ()=>{const r=ri(2,12),t=pick([30,45,60,90,120,135,150,180,240,270]);return mk("expr",`Find the area of a sector with central angle ${t}° in a circle of radius ${r}. Leave your answer in terms of π.`,gpiStr(r*r*t,360),"Sector area = (θ/360)·πr².",`(${t}/360)(π·${r}²) = ${gpiStr(r*r*t,360).replace("pi","π")}`,{pe:`${t}/360*Math.PI*${r}*${r}`})},
  ()=>{const t=pick([30,45,60,90,120,135,150,210,240,270,300,315,330]);return mk("expr",`Convert ${t}° to radians. (Type pi for π.)`,gpiStr(t,180),"Multiply by π/180.",`${t}·π/180 = ${gpiStr(t,180).replace("pi","π")}`,{pe:`${t}*Math.PI/180`})},
  ()=>{const n=ri(1,11),d=pick([2,3,4,6]);if(gcd(n,d)!==1)return null;const deg=180*n/d;if(!Number.isInteger(deg))return null;return mk("num",`Convert ${n===1?"":n}π/${d} radians to degrees.`,deg,"Multiply by 180/π.",`${n===1?"":n}π/${d} · 180/π = ${deg}°`,{js:`180*${n}/${d}`})},
  ()=>{const k=ri(2,9),r2=ri(2,8);return mk("num",`An arc of a circle of radius ${r2} has a central angle of ${k} radians. Find the arc length.`,k*r2,"Arc length s = rθ when θ is in radians.",`s = ${r2}·${k} = ${k*r2}`,{js:`${r2}*${k}`})}].map(gRetry));
T("circ-eq","gcirc","G.GPE.1","Equation of a circle",["pyth","quad-cs"],
 "A circle is all points at a fixed distance r from a center (h, k). The distance formula turns that into the equation (x − h)² + (y − k)² = r².",
 ["Standard form: (x − h)² + (y − k)² = r², center (h, k), radius r.","General form x² + y² + Dx + Ey + F = 0: complete the square in x and in y to reach standard form.","A point is on the circle if its squared distance from the center equals r², inside if less, outside if more."],
 [()=>{const h=ri(-6,6),k=ri(-6,6),r=ri(2,9);const sx=h===0?"x^2":`(x ${h<0?"+":"-"} ${Math.abs(h)})^2`,sy=k===0?"y^2":`(y ${k<0?"+":"-"} ${Math.abs(k)})^2`;
   return mk("eq",`Write the equation of the circle with center (${h}, ${k}) and radius ${r}.`,`${sx} + ${sy} = ${r*r}`,"(x − h)² + (y − k)² = r².",`(x − ${P(h)})² + (y − ${P(k)})² = ${r}² = ${r*r}`,{pe:`(x-(${h}))**2+(y-(${k}))**2-${r*r}`,vars:["x","y","t"]})},
  ()=>{const h=ri(-8,8),k=ri(-8,8),r=ri(2,11);const sx=h===0?"x^2":`(x ${h<0?"+":"-"} ${Math.abs(h)})^2`,sy=k===0?"y^2":`(y ${k<0?"+":"-"} ${Math.abs(k)})^2`;
   return mk("pair",`Find the center of the circle ${sx} + ${sy} = ${r*r}. Give it as an ordered pair.`,`(${h}, ${k})`,"Read h and k from (x − h)² and (y − k)², flipping the signs.",`Center = (${h}, ${k})`,{eqs:[`x=(${h})`,`y=(${k})`]})},
  ()=>{const h=ri(-8,8),k=ri(-8,8),r=ri(2,11);const sx=h===0?"x^2":`(x ${h<0?"+":"-"} ${Math.abs(h)})^2`,sy=k===0?"y^2":`(y ${k<0?"+":"-"} ${Math.abs(k)})^2`;
   return mk("num",`Find the radius of the circle ${sx} + ${sy} = ${r*r}.`,r,"The right side is r².",`r = √${r*r} = ${r}`,{js:`Math.sqrt(${r*r})`})},
  ()=>{const h=ri(-5,5),k=ri(-5,5),r=ri(2,8);const D=-2*h,E=-2*k,F=h*h+k*k-r*r;const sx=h===0?"x^2":`(x ${h<0?"+":"-"} ${Math.abs(h)})^2`,sy=k===0?"y^2":`(y ${k<0?"+":"-"} ${Math.abs(k)})^2`;
   return mk("eq",`Write ${polyStr([[1,"x^2"],[1,"y^2"],[D,"x"],[E,"y"],[F,""]])} = 0 in standard form (complete the square).`,`${sx} + ${sy} = ${r*r}`,"Group x terms and y terms, add (b/2)² to both sides for each.",`x² ${D<0?"−":"+"} ${Math.abs(D)}x + ${h*h} and y² ${E<0?"−":"+"} ${Math.abs(E)}y + ${k*k}; right side ${-F} + ${h*h} + ${k*k} = ${r*r}`,{pe:`x*x+y*y+(${D})*x+(${E})*y+(${F})`,vars:["x","y","t"]})},
  ()=>{const h=ri(-4,4),k=ri(-4,4),r=ri(3,9);const kind=pick(["inside","on","outside"]);let px,py,d2;
   do{px=h+ri(-r-2,r+2);py=k+ri(-r-2,r+2);d2=(px-h)**2+(py-k)**2}while(kind==="on"?d2!==r*r:kind==="inside"?d2>=r*r:d2<=r*r);
   const sx=h===0?"x^2":`(x ${h<0?"+":"-"} ${Math.abs(h)})^2`,sy=k===0?"y^2":`(y ${k<0?"+":"-"} ${Math.abs(k)})^2`;
   return mcq(`Is the point (${px}, ${py}) inside, on, or outside the circle ${sx} + ${sy} = ${r*r}?`,kind,["inside","on","outside"].filter(x=>x!==kind),"Compare the squared distance from the center with r².",`(${px-h})² + (${py-k})² = ${d2} ${d2===r*r?"=":d2<r*r?"<":">"} ${r*r}, so the point is ${kind}.`)},
  ()=>{const h=ri(-5,5),k=ri(-5,5),dx=ri(1,6),dy=ri(1,6);const r2=dx*dx+dy*dy;const sx=h===0?"x^2":`(x ${h<0?"+":"-"} ${Math.abs(h)})^2`,sy=k===0?"y^2":`(y ${k<0?"+":"-"} ${Math.abs(k)})^2`;
   return mk("eq",`A circle has center (${h}, ${k}) and passes through (${h+dx}, ${k+dy}). Write its equation.`,`${sx} + ${sy} = ${r2}`,"Find r² as the squared distance from the center to the point.",`r² = ${dx}² + ${dy}² = ${r2}`,{pe:`(x-(${h}))**2+(y-(${k}))**2-${r2}`,vars:["x","y","t"]})}]);

// ---------------- unit gpoly ----------------
T("poly-angles","gpoly","G.CO.11","Angles of polygons",["tri-ang-sum"],
 "Every polygon can be cut into triangles from one vertex, so its angle sum depends only on the number of sides n.",
 ["Sum of interior angles = (n − 2)·180°.","Each interior angle of a regular n-gon = (n − 2)·180°/n; each exterior angle = 360°/n.","Exterior angles of any convex polygon add to 360°; interior + exterior at a vertex = 180°."],
 [()=>{const n=ri(4,16);return mk("num",`Find the sum of the interior angles of a polygon with ${n} sides.`,(n-2)*180,"(n − 2) × 180°.",`(${n} − 2)·180 = ${(n-2)*180}°`,{js:`(${n}-2)*180`})},
  ()=>{const n=pick([3,4,5,6,8,9,10,12,15,18,20,24,30,36]);return mk("num",`Find the measure of each interior angle of a regular polygon with ${n} sides.`,(n-2)*180/n,"Sum of interior angles ÷ n.",`(${n} − 2)·180 ÷ ${n} = ${(n-2)*180/n}°`,{js:`(${n}-2)*180/${n}`})},
  ()=>{const n=pick([3,4,5,6,8,9,10,12,15,18,20,24,30,36,40,45]);return mk("num",`Find the measure of each exterior angle of a regular polygon with ${n} sides.`,360/n,"Exterior angles add to 360°.",`360 ÷ ${n} = ${360/n}°`,{js:`360/${n}`})},
  ()=>{const n=pick([5,6,8,9,10,12,15,18,20,24,30,36]);const a=(n-2)*180/n;return mk("num",`Each interior angle of a regular polygon measures ${a}°. How many sides does the polygon have?`,n,"Exterior angle = 180° − interior; number of sides = 360° ÷ exterior angle.",`exterior = ${180-a}°; n = 360 ÷ ${180-a} = ${n}`,{js:`360/(180-${a})`})},
  ()=>{const n=ri(4,7),sum=(n-2)*180,x=ri(5,20),co=Array.from({length:n},()=>ri(1,3)),cs=Array.from({length:n-1},()=>ri(1,40));const last=sum-co.reduce((p,c)=>p+c,0)*x-cs.reduce((p,c)=>p+c,0);if(last<1||last>120)return null;cs.push(last);
   const exprs=co.map((c,i)=>`(${lin(c,cs[i])})°`);return mk("num",`The interior angles of a ${["","","","triangle","quadrilateral","pentagon","hexagon","heptagon"][n]} measure ${exprs.join(", ")}. Find x.`,x,"The interior angles add to (n − 2)·180°.",`Sum = ${sum}: ${co.reduce((p,c)=>p+c,0)}x + ${cs.reduce((p,c)=>p+c,0)} = ${sum} → x = ${x}`,{js:`${x}`,eqs:[`${co.map((c,i)=>`(${c})*x+${cs[i]}`).join("+")}=${sum}`]})}].map(gRetry));
T("poly-sym","gpoly","G.CO.3","Symmetry of regular polygons",["poly-angles","rotate"],
 "A figure has symmetry if a rigid motion carries it onto itself. A regular n-gon has n lines of reflection symmetry and n rotations (including the full turn) that map it onto itself.",
 ["Smallest rotation: 360°/n; every multiple of 360°/n also works.","Lines of symmetry of a regular n-gon: n.","A rotation of θ° maps a regular n-gon to itself exactly when θ is a multiple of 360°/n."],
 [()=>{const n=pick([3,4,5,6,8,9,10,12]);return mk("num",`What is the smallest positive angle of rotation (in degrees) that maps a regular ${n}-gon onto itself?`,360/n,"Smallest rotation = 360° ÷ n.",`360 ÷ ${n} = ${360/n}°`,{js:`360/${n}`})},
  ()=>{const n=ri(3,12);return mk("num",`How many lines of reflection symmetry does a regular ${n}-gon have?`,n,"A regular n-gon has n lines of symmetry.",`n = ${n}`,{js:`${n}`})},
  ()=>{const n=pick([4,5,6,8,9,10,12]);const unit=360/n;const yes=Math.random()<0.5;const th=yes?unit*ri(1,3):unit*ri(1,3)+pick([5,10,15,unit/2]);const ok=Number.isInteger(th/unit);
   return mcq(`Does a rotation of ${th}° about its center map a regular ${n}-gon onto itself?`,ok?"Yes":"No",[ok?"No":"Yes"],"Check whether the angle is a multiple of 360°/n.",`360/${n} = ${unit}°; ${th} ÷ ${unit} = ${Math.round(th/unit*100)/100} ${ok?"is a whole number: yes":"is not a whole number: no"}.`)},
  ()=>{const n=pick([3,4,5,6,8,9,10,12]);return mk("num",`A regular ${n}-gon is rotated about its center by ${360/n}° over and over. After how many such rotations does every vertex first return to its starting position?`,n,"After n rotations of 360°/n you have turned a full 360°.",`${n} × ${360/n}° = 360°`,{js:`360/(360/${n})`})}].map(gRetry));
const GQP=[["The diagonals are congruent and bisect each other","rectangle",["rhombus","trapezoid","kite"]],["All four sides are congruent, and the diagonals are perpendicular bisectors of each other","rhombus",["rectangle","trapezoid","kite"]],
 ["The figure has only one pair of parallel sides","trapezoid",["parallelogram","rhombus","rectangle"]],["Opposite sides are parallel and congruent, but neither all angles nor all sides are necessarily equal","parallelogram",["rectangle","rhombus","trapezoid"]],
 ["The diagonals are perpendicular, and exactly one diagonal bisects the other","kite",["parallelogram","rectangle","rhombus"]],["Opposite sides are parallel and all four angles are right angles, but the sides are not necessarily equal","rectangle",["rhombus","kite","trapezoid"]]];
T("quad-props","gpoly","G.CO.11","Properties of quadrilaterals",["poly-angles","cpctc"],
 "Each special quadrilateral has properties that make equations: parallelograms have equal opposite sides and angles with bisecting diagonals; rectangles add congruent diagonals; rhombi add perpendicular diagonals and four equal sides.",
 ["Parallelogram: opposite sides ∥ and =; opposite angles =; consecutive angles supplementary; diagonals bisect each other.","Rectangle: parallelogram with four right angles and congruent diagonals.  Rhombus: parallelogram with four equal sides and perpendicular diagonals that bisect the angles.","Trapezoid midsegment = average of the two bases."],
 [()=>{const {a,b,c,d,x}=gEq();return mk("num",`In parallelogram ABCD, AB = ${lin(a,b)} and CD = ${lin(c,d)}. Find x.`,x,"Opposite sides of a parallelogram are equal.",`${lin(a,b)} = ${lin(c,d)} → x = ${x}`,{js:`${x}`,eqs:[`(${a})*x+${b}=(${c})*x+${d}`]})},
  ()=>{let a,c,x,b,d;do{a=ri(1,5);c=ri(1,5);x=ri(4,20);b=ri(1,20);d=180-(a+c)*x-b}while(d<1);return mk("num",`In parallelogram ABCD, m∠A = (${lin(a,b)})° and m∠B = (${lin(c,d)})°. Find m∠A.`,a*x+b,"Consecutive angles of a parallelogram are supplementary.",`${lin(a,b)} + ${lin(c,d)} = 180 → x = ${x}; m∠A = ${a*x+b}°`,{js:`${a}*${x}+${b}`,eqs:[`(${a})*(${x})+${b}+(${c})*(${x})+${d}=180`]})},
  ()=>{const {a,b,c,d,x}=gEq();return mk("num",`The diagonals of parallelogram ABCD meet at E. AE = ${lin(a,b)} and EC = ${lin(c,d)}. Find AC.`,2*(a*x+b),"Diagonals of a parallelogram bisect each other: AE = EC, and AC = 2·AE.",`${lin(a,b)} = ${lin(c,d)} → x = ${x}; AE = ${a*x+b}, AC = ${2*(a*x+b)}`,{js:`2*(${a}*${x}+${b})`,eqs:[`(${a})*(${x})+${b}=(${c})*(${x})+${d}`]})},
  ()=>{const [a,b,c]=pick(GTT),k=ri(1,3);return mk("num",`The diagonals of a rhombus measure ${2*a*k} and ${2*b*k}. Find the length of a side.`,c*k,"The diagonals of a rhombus are perpendicular bisectors: each side is the hypotenuse of a right triangle with legs half of each diagonal.",`√(${a*k}² + ${b*k}²) = ${c*k}`,{js:`Math.hypot(${2*a*k}/2,${2*b*k}/2)`})},
  ()=>{const b1=ri(4,20),b2=ri(4,20);if((b1+b2)%2)return null;const m=(b1+b2)/2;return mk("num",`The bases of a trapezoid are ${b1} and ${b2}. Find the length of its midsegment.`,m,"Midsegment = (base₁ + base₂)/2.",`(${b1} + ${b2})/2 = ${m}`,{js:`(${b1}+${b2})/2`})},
  ()=>{const [s,ans,wr]=pick(GQP);return mcq(`Which quadrilateral is described? “${s}.”`,ans,wr,"Match the properties to the most specific quadrilateral.",`${s} describes a ${ans}.`)}].map(gRetry));
const gClass=(P)=>{const d=(i,j)=>Math.hypot(P[j][0]-P[i][0],P[j][1]-P[i][1]),v=(i,j)=>[P[j][0]-P[i][0],P[j][1]-P[i][1]],cr=(u,w)=>u[0]*w[1]-u[1]*w[0],dt=(u,w)=>u[0]*w[0]+u[1]*w[1];
  const par=(a,b,c,e)=>cr(v(a,b),v(c,e))===0;const pgm=par(0,1,3,2)&&par(1,2,0,3);if(!pgm)return (par(0,1,3,2)||par(1,2,0,3))?"trapezoid":"other";
  const rect=dt(v(0,1),v(1,2))===0,rh=Math.abs(d(0,1)-d(1,2))<1e-9;return rect&&rh?"square":rect?"rectangle":rh?"rhombus":"parallelogram"};
T("quad-coord","gpoly","G.GPE.4","Quadrilaterals on the coordinate plane",["dist-mid","quad-props","parallel-perp"],
 "Coordinates let us prove what kind of figure we have: use slopes for parallel and perpendicular sides, the distance formula for lengths, and midpoints for diagonals.",
 ["Parallelogram: both pairs of opposite sides have equal slopes (or the diagonals share a midpoint).","Rectangle: a parallelogram with a right angle (perpendicular slopes, product −1). Rhombus: a parallelogram with equal adjacent sides. Square: both.","Missing vertex D of parallelogram ABCD: D = A + C − B (diagonals share the midpoint)."],
 [()=>{const ax=ri(-6,6),ay=ri(-6,6),bx=ri(-6,6),by=ri(-6,6),cx=ri(-6,6),cy=ri(-6,6);if((bx-ax)*(cy-by)-(by-ay)*(cx-bx)===0)return null;return mk("pair",`Three consecutive vertices of parallelogram ABCD are A(${ax}, ${ay}), B(${bx}, ${by}) and C(${cx}, ${cy}). Find D.`,`(${ax+cx-bx}, ${ay+cy-by})`,"The diagonals AC and BD share a midpoint, so D = A + C − B.",`(${ax} + ${P(cx)} − ${P(bx)}, ${ay} + ${P(cy)} − ${P(by)}) = (${ax+cx-bx}, ${ay+cy-by})`,{eqs:[`x+(${bx})=(${ax})+(${cx})`,`y+(${by})=(${ay})+(${cy})`]})},
  ()=>{const kinds=["parallelogram","rectangle","rhombus","square","trapezoid"];const kind=pick(kinds);let pts;let tries=0;
   do{tries++;const ox=ri(-5,3),oy=ri(-5,3);let u,w;
     if(kind==="square"){const a=ri(1,4),b=ri(0,4);u=[a,b];w=[-b,a];if(a===0&&b===0)continue}
     else if(kind==="rectangle"){const a=ri(1,3),b=ri(0,3),t=pick([2,3]);u=[a,b];w=[-b*t,a*t];if(a*a+b*b===0)continue;}
     else if(kind==="rhombus"){const p=ri(1,5),q=ri(1,5);u=[p,q];w=[q,p]}
     else if(kind==="parallelogram"){u=[ri(1,5),ri(0,4)];w=[ri(-3,3),ri(1,5)]}
     else{u=[ri(2,6),0];w=[ri(0,3),ri(2,4)];pts=[[ox,oy],[ox+u[0],oy],[ox+w[0]+u[0]-ri(1,1),oy+w[1]],[ox+w[0],oy+w[1]]];if(pts[1][0]-pts[0][0]===pts[2][0]-pts[3][0])pts[2][0]+=1;continue_ok:null}
     if(kind!=="trapezoid")pts=[[ox,oy],[ox+u[0],oy+u[1]],[ox+u[0]+w[0],oy+u[1]+w[1]],[ox+w[0],oy+w[1]]]}
   while(tries<200&&gClass(pts)!==kind);
   if(gClass(pts)!==kind)return null;
   const names=["A","B","C","D"];const lst=pts.map((p,i)=>`${names[i]}(${p[0]}, ${p[1]})`).join(", ");
   const cat=["parallelogram","rectangle","rhombus","square","trapezoid"];
   return mcq(`The vertices of quadrilateral ABCD are ${lst}. What is the most specific name for ABCD?`,kind,cat.filter(c=>c!==kind).slice(0,4),"Compare slopes (parallel/perpendicular) and side lengths (equal?).",`Using the slopes and distances: ABCD is a ${kind}.`)},
  ()=>{const y=ri(-4,4),x1=ri(-6,3),x2=x1+ri(2,8),x3=ri(-6,6),y3=y+pick([-1,1])*ri(2,9);const A=Math.abs(x2-x1)*Math.abs(y3-y)/2;
   return mk("num",`Find the area of the triangle with vertices (${x1}, ${y}), (${x2}, ${y}) and (${x3}, ${y3}).`,A,"The base lies on a horizontal line: area = ½ × base × height.",`base = ${x2-x1}, height = ${Math.abs(y3-y)}; ½·${x2-x1}·${Math.abs(y3-y)} = ${A}`,{js:`Math.abs((${x1})*((${y})-(${y3}))+(${x2})*((${y3})-(${y}))+(${x3})*((${y})-(${y})))/2`})},
  ()=>{const [a,b,c]=pick(GTT),k=ri(1,2),x1=ri(-6,6),y1=ri(-6,6),s1=pick([-1,1]),s2=pick([-1,1]);const P1=[x1,y1],P2=[x1+s1*a*k,y1],P3=[x1+s1*a*k,y1+s2*b*k];
   return mk("num",`Find the perimeter of the triangle with vertices (${P1}), (${P2}) and (${P3}).`.replace(/\((-?\d+),(-?\d+)\)/g,"($1, $2)"),(a+b+c)*k,"Use the distance formula (or Pythagorean triples) on each side.",`Sides: ${a*k}, ${b*k} and ${c*k}; perimeter ${(a+b+c)*k}`,{js:`Math.hypot(${P2[0]-P1[0]},0)+Math.hypot(0,${P3[1]-P2[1]})+Math.hypot(${P3[0]-P1[0]},${P3[1]-P1[1]})`})}].map(gRetry));
T("perp-bis","gcoord","G.CO.9","Perpendicular & angle bisectors",["dist-mid","parallel-perp"],
 "Every point on the perpendicular bisector of a segment is the same distance from both endpoints, and every point on an angle bisector is the same distance from both sides of the angle.",
 ["Perpendicular bisector of AB: passes through the midpoint with slope −1/(slope of AB). Its points P satisfy PA = PB.","Angle bisector: points are equidistant from the two sides.","Circumcenter (perpendicular bisectors) is equidistant from the vertices; incenter (angle bisectors) is equidistant from the sides."],
 [()=>{const m=pick([-3,-2,-1,1,2,3]),c=ri(-6,6),p=ri(-4,4),q=m*p+c,t=ri(1,3);const A=[p-t*m,q+t],B=[p+t*m,q-t];return mk("eq",`Write the equation of the perpendicular bisector of the segment with endpoints A(${A[0]}, ${A[1]}) and B(${B[0]}, ${B[1]}) in the form y = mx + b.`,`y = ${lin(m,c)}`,"The bisector passes through the midpoint with the negative reciprocal slope.",`Midpoint (${p}, ${q}); slope of AB = ${-1/m>0?"":"−"}${gfr(1,Math.abs(m))}... so bisector slope = ${m}; b = ${q} − ${m}·${P(p)} = ${c}`.replace("... so","; so"),{pe:`y-(${m})*x-(${c})`,vars:["x","y","t"]})},
  ()=>{const {a,b,c,d,x}=gEq();return mk("num",`Point P is on the perpendicular bisector of AB. PA = ${lin(a,b)} and PB = ${lin(c,d)}. Find PA.`,a*x+b,"Points on the perpendicular bisector are equidistant from the endpoints.",`${lin(a,b)} = ${lin(c,d)} → x = ${x}; PA = ${a*x+b}`,{js:`${a}*${x}+${b}`,eqs:[`(${a})*(${x})+${b}=(${c})*(${x})+${d}`]})},
  ()=>{const {a,b,c,d,x}=gEq();return mk("num",`Point P lies on the bisector of ∠ABC. The distance from P to BA is ${lin(a,b)} and the distance from P to BC is ${lin(c,d)}. Find x.`,x,"Points on an angle bisector are equidistant from the sides of the angle.",`${lin(a,b)} = ${lin(c,d)} → x = ${x}`,{js:`${x}`,eqs:[`(${a})*x+${b}=(${c})*x+${d}`]})},
  ()=>{const ax=ri(-5,5),ay=ri(-5,5);let dx,dy;do{dx=2*ri(-3,3);dy=2*ri(-3,3)}while(dx===0&&dy===0);const bx=ax+dx,by=ay+dy,mx=ax+dx/2,my=ay+dy/2;
   const g=gcd(Math.abs(dx),Math.abs(dy)),ux=-dy/g,uy=dx/g;const t=ri(1,3)*pick([-1,1]);const good=[mx+t*ux,my+t*uy];const eqd=p=>Math.abs(Math.hypot(p[0]-ax,p[1]-ay)-Math.hypot(p[0]-bx,p[1]-by))<1e-9;
   const wr=new Set();let tries=0;while(wr.size<3&&tries++<500){const p=[ri(-9,9),ri(-9,9)];if(!eqd(p))wr.add(`(${p[0]}, ${p[1]})`)}
   if(wr.size<3||!eqd(good))return null;return mcq(`Which point lies on the perpendicular bisector of the segment with endpoints A(${ax}, ${ay}) and B(${bx}, ${by})?`,`(${good[0]}, ${good[1]})`,[...wr],"A point on the perpendicular bisector is equidistant from A and B.",`(${good[0]}, ${good[1]}) is ${Math.hypot(good[0]-ax,good[1]-ay).toFixed(2)} from both A and B.`)}].map(gRetry));

// ---------------- unit gsolid ----------------
T("area-trig","gsolid","G.SRT.9","Area with trigonometry & Heron's formula",["trig-solve","special-rt"],
 "When you know two sides and the angle between them, the area of a triangle is ½ab·sin C. Heron's formula handles three known sides. Regular polygons split into congruent triangles.",
 ["Triangle: A = ½·a·b·sin C. Parallelogram: A = a·b·sin θ.","Heron: s = (a + b + c)/2, A = √(s(s − a)(s − b)(s − c)).","Equilateral triangle of side s: A = (√3/4)s². Regular hexagon: six equilateral triangles."],
 [()=>{const a=ri(5,30),b=ri(5,30),C=ri(20,150);const v=0.5*a*b*Math.sin(C*Math.PI/180);if(!gok(v))return null;return mk("num",`Find the area of a triangle with sides ${a} and ${b} and an included angle of ${C}°. Round to the nearest tenth.`,rdn(v,1),"A = ½ab sin C.",`½·${a}·${b}·sin ${C}° ≈ ${rdn(v,1)}`,{js:`0.5*${a}*${b}*Math.sin(${C}*Math.PI/180)`,jtol:0.051})},
  ()=>{const a=ri(5,30),b=ri(5,30),C=ri(25,85);const v=a*b*Math.sin(C*Math.PI/180);if(!gok(v))return null;return mk("num",`A parallelogram has adjacent sides ${a} and ${b} with an angle of ${C}° between them. Find its area to the nearest tenth.`,rdn(v,1),"A = ab sin θ.",`${a}·${b}·sin ${C}° ≈ ${rdn(v,1)}`,{js:`${a}*${b}*Math.sin(${C}*Math.PI/180)`,jtol:0.051})},
  ()=>{const k=ri(1,8);return mk("expr",`Find the area of an equilateral triangle with side length ${2*k}. Leave the answer as a simplified radical.`,k*k===1?"sqrt(3)":`${k*k}sqrt(3)`,"A = (√3/4)s².",`(√3/4)(${2*k})² = ${k*k}√3`,{form:"rad",pe:`Math.sqrt(3)/4*${(2*k)**2}`})},
  ()=>{const k=ri(1,6);return mk("expr",`Find the area of a regular hexagon with side length ${2*k}. Leave the answer as a simplified radical.`,`${6*k*k}sqrt(3)`,"A regular hexagon is six equilateral triangles: 6·(√3/4)s².",`6·(√3/4)(${2*k})² = ${6*k*k}√3`,{form:"rad",pe:`6*Math.sqrt(3)/4*${(2*k)**2}`})},
  ()=>{const T4=[[13,14,15,84],[5,5,6,12],[6,25,29,60],[7,15,20,42],[9,10,17,36],[10,13,13,60],[3,4,5,6],[4,13,15,24]];const [a,b,c,A]=pick(T4),k=ri(1,3);return mk("num",`Use Heron's formula to find the area of a triangle with sides ${a*k}, ${b*k} and ${c*k}.`,A*k*k,"s = (a + b + c)/2, then A = √(s(s−a)(s−b)(s−c)).",`s = ${(a+b+c)*k/2}; A = √(${(a+b+c)*k/2}·${(a+b+c)*k/2-a*k}·${(a+b+c)*k/2-b*k}·${(a+b+c)*k/2-c*k}) = ${A*k*k}`,{js:`(()=>{const a=${a*k},b=${b*k},c=${c*k},s=(a+b+c)/2;return Math.sqrt(s*(s-a)*(s-b)*(s-c))})()`})}].map(gRetry));
T("vol-solids","gsolid","G.GMD.3","Volume of cylinders, cones, pyramids & spheres",["cyl-cone-sph","vol-prism","circle-basic"],
 "Volume formulas come from slicing and comparing solids (Cavalieri's principle). A pyramid or cone holds one third of the prism or cylinder with the same base and height.",
 ["Cylinder πr²h; cone ⅓πr²h; sphere (4/3)πr³; pyramid ⅓·(base area)·h; prism (base area)·h.","Leave answers 'in terms of π' unless told to round.","To find a missing dimension, substitute the volume into the formula and solve."],
 [()=>{const r=ri(2,10),h=ri(2,15);return mk("expr",`Find the volume of a cylinder with radius ${r} and height ${h}. Leave your answer in terms of π.`,`${r*r*h}pi`,"V = πr²h.",`π·${r}²·${h} = ${r*r*h}π`,{pe:`Math.PI*${r*r*h}`})},
  ()=>{const r=ri(2,9),h=3*ri(1,6);return mk("expr",`Find the volume of a cone with radius ${r} and height ${h}. Leave your answer in terms of π.`,`${r*r*h/3}pi`,"V = ⅓πr²h.",`⅓·π·${r}²·${h} = ${r*r*h/3}π`,{pe:`Math.PI*${r*r*h}/3`})},
  ()=>{const r=ri(2,9);return mk("expr",`Find the volume of a sphere with radius ${r}. Leave your answer in terms of π.`,gpiStr(4*r*r*r,3),"V = (4/3)πr³.",`(4/3)·π·${r}³ = ${gpiStr(4*r*r*r,3).replace("pi","π")}`,{pe:`4/3*Math.PI*${r*r*r}`})},
  ()=>{const s=3*ri(1,5),h=ri(2,12),t=ri(1,3);return mk("num",`A square pyramid has a base with side ${s} and height ${h}. Find its volume.`,s*s*h/3,"V = ⅓·(base area)·height.",`⅓·${s}²·${h} = ${s*s*h/3}`,{js:`${s}*${s}*${h}/3`})},
  ()=>{const r=ri(2,9),h=ri(2,12);return mk("num",`A cylinder has volume ${r*r*h}π and radius ${r}. Find its height.`,h,"V = πr²h, so h = V ÷ (πr²).",`${r*r*h}π ÷ (π·${r}²) = ${h}`,{js:`${r*r*h}/(${r}*${r})`})},
  ()=>{const r=ri(2,8);return mk("expr",`Find the volume of a hemisphere with radius ${r*3}. Leave your answer in terms of π.`,`${18*r*r*r}pi`,"A hemisphere is half a sphere: ½·(4/3)πr³ = (2/3)πr³.",`(2/3)π(${r*3})³ = ${18*r*r*r}π`,{pe:`2/3*Math.PI*${27*r*r*r}`})}]);
T("cross-sect","gsolid","G.GMD.4","Cross sections & solids of revolution",["vol-solids"],
 "Slicing a solid with a plane gives a two-dimensional cross section; spinning a flat figure about a line sweeps out a solid of revolution.",
 ["Rotating a rectangle about one of its sides gives a cylinder; a right triangle about a leg gives a cone; a semicircle about its diameter gives a sphere; a circle gives a sphere.","A plane parallel to the base of a prism, cylinder, pyramid or cone gives a cross section congruent (prism/cylinder) or similar (pyramid/cone) to the base.","Volume of the solid of revolution = use the formula with the correct radius (distance from the axis) and height."],
 [()=>{const items=[["a rectangle about one of its sides","cylinder"],["a right triangle about one of its legs","cone"],["a semicircle about its diameter","sphere"],["a circle about one of its diameters","sphere"]];const [d,a]=pick(items);return mcq(`What solid is formed by rotating ${d} in space?`,a,["cylinder","cone","sphere","pyramid","prism"].filter(x=>x!==a).slice(0,3),"Picture the figure spinning around the axis.",`Rotating ${d} produces a ${a}.`)},
  ()=>{const items=[["a cube","parallel to a face","square"],["a sphere","through its center","circle"],["a cylinder","parallel to its bases","circle"],["a cylinder","perpendicular to its bases through the axis","rectangle"],["a cone","parallel to its base","circle"],["a square pyramid","parallel to its base","square"],["a right rectangular prism","parallel to a base","rectangle"]];const [s,p,a]=pick(items);
   return mcq(`What is the shape of the cross section of ${s} cut by a plane ${p}?`,a,["square","circle","rectangle","triangle","trapezoid"].filter(x=>x!==a).slice(0,3),"Picture the slice.",`The slice is a ${a}.`)},
  ()=>{const w=ri(2,9),h=ri(2,12);return mk("expr",`A ${w} by ${h} rectangle is rotated about a side of length ${h}. Find the volume of the solid formed in terms of π.`,`${w*w*h}pi`,"The solid is a cylinder with radius w (the other side) and height h (the side on the axis).",`V = π·${w}²·${h} = ${w*w*h}π`,{pe:`Math.PI*${w}*${w}*${h}`})},
  ()=>{const r=ri(2,9),h=3*ri(1,5);return mk("expr",`A right triangle with legs ${r} and ${h} is rotated about the leg of length ${h}. Find the volume of the cone formed in terms of π.`,`${r*r*h/3}pi`,"The leg on the axis is the height; the other leg is the radius. V = ⅓πr²h.",`⅓·π·${r}²·${h} = ${r*r*h/3}π`,{pe:`Math.PI*${r}*${r}*${h}/3`})}]);
T("sim-solids","gsolid","G.GMD.3","Scaling solids: lengths, areas & volumes",["sim-tri","vol-solids"],
 "If two solids are similar with scale factor k, every length scales by k, every area (surface or base) by k², and every volume by k³.",
 ["Ratio of lengths a : b → areas a² : b² → volumes a³ : b³.","Convert between them: from a volume ratio take the cube root to get the scale factor.","Check the units: area ratio gets squared, volume ratio cubed."],
 [()=>{const a=ri(1,4);let b;do{b=ri(2,5)}while(b===a||gcd(a,b)!==1);const V=a**3*ri(1,5);return mk("num",`Two similar solids have corresponding lengths in the ratio ${a} : ${b}. The volume of the smaller (first) solid is ${V}. Find the volume of the second.`,V*b**3/a**3,"Volumes scale by the cube of the length ratio.",`${V}·(${b}/${a})³ = ${V*b**3/a**3}`,{js:`${V}*${b}**3/${a}**3`})},
  ()=>{const a=ri(1,4);let b;do{b=ri(2,6)}while(b===a||gcd(a,b)!==1);const A=a*a*ri(1,6);return mk("num",`Two similar solids have corresponding lengths in the ratio ${a} : ${b}. The surface area of the first is ${A}. Find the surface area of the second.`,A*b*b/(a*a),"Areas scale by the square of the length ratio.",`${A}·(${b}/${a})² = ${A*b*b/(a*a)}`,{js:`${A}*${b}**2/${a}**2`})},
  ()=>{const a=ri(1,4);let b;do{b=ri(2,5)}while(b===a||gcd(a,b)!==1);const k=ri(1,3);return mk("num",`Two similar solids have volumes ${k*a**3} and ${k*b**3}. What is the ratio of their corresponding lengths (first : second) as a fraction a/b?`,gfr(a,b),"The length ratio is the cube root of the volume ratio.",`∛(${k*a**3}/${k*b**3}) = ${a}/${b}`,{js:`${a}/${b}`})},
  ()=>{const k=ri(2,4);const r=ri(2,6);return mk("num",`A model of a cylindrical tank is built with every dimension ${k} times as large as the original. The original holds ${r*r*r} liters. How many liters does the larger tank hold?`,r*r*r*k**3,"Volume scales by k³.",`${r*r*r}·${k}³ = ${r*r*r*k**3}`,{js:`${r*r*r}*${k}**3`})}]);
T("density","gsolid","G.MG.2","Density & modeling with geometry",["vol-solids","pct-apps"],
 "Geometry models real situations: density relates mass and volume, and area or volume formulas answer questions about cost, capacity and crowding.",
 ["Density = mass ÷ volume (mass = density × volume). Population density = people ÷ area.","Make sure all lengths use the same unit before computing area or volume.","Rates multiply: cost = (price per unit) × (number of units of area or volume)."],
 [()=>{const l=ri(2,12),w=ri(2,10),h=ri(2,10),d=pick([2.7,7.8,1.2,8.9,0.9,11.3,19.3]);const m=Math.round(d*l*w*h*10)/10;return mk("num",`A metal block is ${l} cm by ${w} cm by ${h} cm and has density ${d} g/cm³. Find its mass in grams.`,rdn(m,1),"mass = density × volume.",`Volume = ${l*w*h} cm³; mass = ${d}·${l*w*h} = ${rdn(m,1)} g`,{js:`${d}*${l}*${w}*${h}`,jtol:0.051})},
  ()=>{const l=ri(2,10),w=ri(2,10),h=ri(2,10),d=ri(2,12);const m=d*l*w*h;return mk("num",`A rectangular block with dimensions ${l} cm by ${w} cm by ${h} cm has a mass of ${m} grams. Find its density in g/cm³.`,d,"density = mass ÷ volume.",`${m} ÷ ${l*w*h} = ${d}`,{js:`${m}/(${l}*${w}*${h})`})},
  ()=>{const A=ri(5,40)*ri(2,9),p=ri(20,90);const pop=A*p;return mk("num",`A town has ${pop} people living on ${A} square miles. What is its population density in people per square mile?`,p,"Population density = people ÷ area.",`${pop} ÷ ${A} = ${p}`,{js:`${pop}/${A}`})},
  ()=>{const r=ri(2,9),h=ri(3,20);const v=3.14*r*r*h;return mk("num",`A cylindrical can has radius ${r} cm and height ${h} cm. Using π = 3.14, how many cubic centimeters of soup does it hold? (Round to the nearest hundredth if needed.)`,rdn(v,2),"V = πr²h.",`3.14·${r}²·${h} = ${rdn(v,2)}`,{js:`3.14*${r}*${r}*${h}`,jtol:0.0051})},
  ()=>{const l=ri(10,40),w=ri(8,30),c=pick([1.5,2,2.5,3.25,4]);const cost=Math.round(l*w*c*100)/100;return mk("num",`A rectangular patio ${l} ft by ${w} ft will be covered with tile that costs $${c} per square foot. What is the total cost in dollars?`,rdn(cost,2),"cost = (price per square foot) × (area).",`Area = ${l*w} ft²; cost = ${c}·${l*w} = ${rdn(cost,2)}`,{js:`${c}*${l}*${w}`,jtol:0.0051})}]);
